-- ===== 본문 재추출 반영 1/2 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 70행 / 전체 86행

UPDATE public.words SET meaning = '가상자산(Virtual Asset)은 분산원장 및 암호화 기술을 바탕으로 민간에 의해 디지털 토큰형태로 발행되어 전자적으로 거래 또는 이전 가능한 자산이다.', detailed_meaning = '가상자산(Virtual Asset)은 분산원장 및 암호화 기술을 바탕으로 민간에 의해 디지털 토큰형태로 발행되어 전자적으로 거래 또는 이전 가능한 자산이다. 「가상자산 이용자 보호 등 에 관한 법률」에서는 “경제적 가치를 지닌 것으로서 전자적으로 거래 또는 이전될 수 있는 전자적 증표와 그에 관한 일체의 권리”로 정의하며, 발행인이 사용처와 용도를 제한한 것, 게임물의 이용을 통해 획득한 결과물, 전자화폐, 전자증권, 전자어음 등은 가상자산에서 제외하고 있다. 가상자산은 전통적인 현금, 예금 등의 화폐와는 구별되는 새로운 형태의 자산으로서 일부에서 투자 및 지급수단으로 활용되고 있으나, 가격 변동성이 크고, 신뢰성과 안정성 측면에서 기존 금융자산과 차이가 있다. 국제자금세탁방지기구(FATF; Financial Action Task Force)는 “디지털 방식으로 거래, 이전될 수 있으며, 지급 또는 투자 목적으로 사용될 수 있는 가치의 디지털 증표(digital representation of value)”로 정의하며 법정통화의 디지털 증표라고 할 수 있는 중앙은행 디지털화폐(CBDC)나 증권 등 기존 금융자산의 디지털 표현 형태는 포함되지 않는다. 한국은행은 가상자산이 금융시스템과 통화정책, 지급결제시스템에 미치는 영향에 대해 지속적으로 연구하고 있으며, 국제기구 등과의 협력을 통해 가상자산 시장의 투명성 및 이용자 보호 강화 등을 위한 정책적기반 마련을 위해 노력하고 있다.', related_words = ARRAY['블록체인','비트코인','중앙은행 디지털화폐(CBDC)']::text[] WHERE id = 7;  -- 가상자산
UPDATE public.words SET meaning = '간편 송금은 모바일 앱이나 온라인 서비스를 통해 상대방에게 손쉽게 금전적 가치를 이전해 주는 서비스이다.', detailed_meaning = '간편 송금은 모바일 앱이나 온라인 서비스를 통해 상대방에게 손쉽게 금전적 가치를 이전해 주는 서비스이다. 이용이 다소 복잡하고 불편한 공인인증서나 OTP(One Time Password, 일회용 비밀번호) 없이도 비밀번호 또는 지문인식과 같은 생체인증만으로 송금이 가능하기 때문에 사용자가 편리함을 느끼게 된다. 국내에서는 토스, 카카오페이, 네이버페이 등이 간편 송금 방식을 이용하고 있다.', related_words = ARRAY['NFC 기술']::text[] WHERE id = 11;  -- 간편 송금
UPDATE public.words SET meaning = '금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다.', detailed_meaning = '금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다. 바젤Ⅱ에서는 이러한 편중리스크를 직접 규율하지 않고 각국 감독당국이 편중리스크를 점검·관리하도록 하였다. 우리나라는 은행법 등에서 동일인·동일차주 신용공여 한도 제도를 통해 편중리스크를 관리하고 있다. 한편 금융위기 이후 금융기관간 상호연계성에 의 한 시스템 리스크를 억제하고 편중리스크의 근본적인 관리 필요성이 대두됨에 따라 바젤위원회(BCBS)는 거액익스포저 규제를 2019년 1월 도입하였고 우리나라는 2019년 3월시범실시한 이후 2024년 2월부터 시행 중이다. 동 규제는 거액익스포저를 단일 거래상대방 또는 연계된 거래상대방그룹(경제적 상호의존성이 있는 거래상대방들로 구성되어 거래상대방들 중 하나가 파산하면 다른 모든 거래상대방들이 파산할 가능성이 상당히 높은 그룹)에 대한 익스포저의 합계가 은행 기본자본의 10% 이상인 경우로 정의하고, 거액익스포저 현황을 금융당국에 정기적으로 보고하도록 하는 한편, 거액익스포저비율(거액익스포저를 은행 기본자본으로 나눈 값)이 25%를 초과하지 못하도록 하고 있다.', related_words = ARRAY['동일인 신용공여한도제(동일인 여신한도제)','익스포저']::text[] WHERE id = 16;  -- 거액익스포저 규제
UPDATE public.words SET meaning = '지급결제시스템을 통해 이루어진 참가기관의 지급지시가 결제된 이후에는 어떠한 상황이나 법률에 의해서도 취소되거나 무효화되지 않고 해당 지급결제시스템의 운영 규칙에 따라 무조건적으로 종결되는 것을', detailed_meaning = '지급결제시스템을 통해 이루어진 참가기관의 지급지시가 결제된 이후에는 어떠한 상황이나 법률에 의해서도 취소되거나 무효화되지 않고 해당 지급결제시스템의 운영 규칙에 따라 무조건적으로 종결되는 것을 의미한다. 결제완결성(Settlement Finality)이 보장되지 않을 경우 지급결제시스템을 통해 종결된 금융기관의 지급지시가 사후적으로 무효화될 수 있어 금융시스템에 큰 혼란을 초래할 수 있다. 「지급 및 시장인프라 위원회」 (CPMI)와 「국제증권감독기구」(IOSCO)가 제정한 국제기준인 「금융시장인프라에 관한 원칙」(PFMI)에서도 결제완결성 원칙이 규정되어 있어 각국 정책당국이 준수하도록 하고 있다. 우리나라는 2006년 4월 시행된 「채무자회생 및 파산에 관한 법률」에서 지급결제시스템에 대한 결제완결성 보장 제도가 도입되었다. 동 법에 따라 한국은행 총재는 금융위원회 위원장과 협의하여 결제완결성이 보장되는 지급결제시스템을 지정할 수 있으며, 지정된 지급결제시스템을 통해 결제된 지급행위는 참가기관의 파산 등의 사유로 취소할수 없도록 하고 있다.', related_words = '{}'::text[] WHERE id = 20;  -- 결제완결성
UPDATE public.words SET meaning = '경기순응성이란 통상 경제주체의 위험인식 및 행위, 금융의 제도 및 규제 등의 효과가 경기변동의 움직임과 같은 방향으로 움직이는 것을 의미한다.', detailed_meaning = '경기순응성이란 통상 경제주체의 위험인식 및 행위, 금융의 제도 및 규제 등의 효과가 경기변동의 움직임과 같은 방향으로 움직이는 것을 의미한다. 예를 들어 은행대출의 경우호경기에는 미래에 대한 낙관적 기대 등으로 여신심사기준도 완화되어 더 크게 증가하여 경기확장에 기여한다. 반면 불경기에는 심사기준이 강화되어 대출이 큰 폭으로 감소하여 불황을 더욱 부추기게 된다. 이러한 은행대출의 경기순응적 행태는 신용팽창 또는 위축을 가속시킴으로서 경기변동의 진폭을 더욱 크게 한다. 따라서 정책당국은 정책을 마련할 경우 경기순응성을 완화할 수 있는 경기대응적 정책수단을 개발하기 위해 노력하고 있다.', related_words = ARRAY['거시건전성 정책']::text[] WHERE id = 23;  -- 경기순응성
UPDATE public.words SET meaning = '경영실태평가는 금융감독당국이 임점 검사 시 금융기관의 경영실태 전반을 점검·평가 하기 위한 제도로, 각 금융기관의 경영실적, 경영의 건전성, 경영진의 경영능력, 법규준수 상황 및 리스크 관리실태', detailed_meaning = '경영실태평가는 금융감독당국이 임점 검사 시 금융기관의 경영실태 전반을 점검·평가 하기 위한 제도로, 각 금융기관의 경영실적, 경영의 건전성, 경영진의 경영능력, 법규준수 상황 및 리스크 관리실태 등 다양한 평가부문을 종합적이고 통일적인 방식에 따라 일정한 등급으로 평가하여 금융기관의 경영상태를 체계적이고 객관적으로 확인하는 방법의 하나이다. 아울러 평가 결과에 따라 부실금융기관에 대해 적기시정조치를 취하는 한 편 감독상 주의 및 관심을 더욱 집중하여 금융기관 경영의 건전성 확보와 금융소비자 보호 등 감독·검사 업무의 효율성을 높일 수 있다. 우리나라는 1996년 10월 은행에 도입한 이후 다른 금융기관에 확대 적용하였다. 경영실태평가의 평가절차나 방식 등은 금융기관별로 거의 동일하나, 금융기관 그룹별 특성에 따라 평가부문과 항목에 차이가 있다. 은행의 경우 해당 은행의 특성(일반은행, 외은지점, 특수은행 등)에 따라 CAMEL-IR방식, ROCA 방식, CACREL 방식을 운용하고 있다. 경영실태평가의 부문별 평가등급 및종합등급은 1등급(우수), 2등급(양호), 3등급(보통), 4등급(취약), 5등급(위험)의 5단계로 구분되며, 일반은행의 경우 각 등급을 3단계(+, 0, -)로 세분화하여 5등급, 15단계로 운용하고 있다.', related_words = ARRAY['CAMEL-IR 방식/ROCA 방식/CACREL 방식']::text[] WHERE id = 27;  -- 경영실태평가/은행경영실태 평가등급제도
UPDATE public.words SET meaning = '다양한 경제지표와 세계 경제 동향 등을 바탕으로 향후 경제 상황이 어떻게 전개될지를 분석하고 예측한 보고서를 말한다.', detailed_meaning = '다양한 경제지표와 세계 경제 동향 등을 바탕으로 향후 경제 상황이 어떻게 전개될지를 분석하고 예측한 보고서를 말한다. 경제전망에는 보통 한 나라의 경제가 얼마나 성장할지 예측하는 경제성장률 전망, 물가가 얼마나 오를지 분석하는 인플레이션 전망, 일자리사정을 예측하는 고용 전망, 외환시장 변동성 및 환율을 살펴보는 환율 전망, 수출입 추세와 무역수지를 예측하는 경상수지 전망 등이 포함된다. 경제주체들이 어떤 경제행위를 결정할 때 경기판단과 예측의 정확성 여부에 따라 미래의 경제적 성과가 크게 달라질 수 있으므로 경제전망은 중요하다. 가계는 경제전망에 따라 재화·서비스, 주택, 주식 등의 구입 시기를 결정한다. 기업은 제품에 대한 수요 전망을 통해 생산량과 시설 투자 계획을 수립한다. 중앙은행은 경기 및 물가 전망을 바탕으로 경제성장과 물가안정을 이루기 위해통화량 및 금리 운용계획을 결정하며, 정부 또한 경제전망에 기초하여 예산 편성, 재정지출 등을 확정한다. 한국은행, IMF, OECD, 각종 민간경제연구소 등 국내외 여러 기관은 정기적으로 경제전망을 발표하고 있다.', related_words = ARRAY['경제성장률','인플레이션','경상수지','경기']::text[] WHERE id = 31;  -- 경제전망보고서
UPDATE public.words SET meaning = '소비자물가지수를 구성하는 품목들은 가격이 경직적으로 움직이는 품목과 신축적으로 움 직이는 품목으로 나누어 볼 수 있는데, 그중 경직적으로 움직이는 품목들을 대상으로 만든물가지수를 경직적 물가지수,', detailed_meaning = '소비자물가지수를 구성하는 품목들은 가격이 경직적으로 움직이는 품목과 신축적으로 움 직이는 품목으로 나누어 볼 수 있는데, 그중 경직적으로 움직이는 품목들을 대상으로 만든물가지수를 경직적 물가지수, 신축적으로 움직이는 품목을 대상으로 한 물가지수를 신축적 물가지수라고 한다. 정부의 직·간접적인 영향을 크게 받는 공공서비스, 전기·수도, 담배, 보육·급식 가격이나 개인서비스 요금 등은 대체로 가격이 쉽게 오르거나 내리지 않는 특징을 보이므로 경직적 물가를 구성하는 주요 품목이다. 이러한 경직적 물가의 변동은 장기적인 인플레이션 흐름을 잘 반영하므로 향후 물가 기조를 예측하는데 유용한 지표이다.', related_words = ARRAY['근원인플레이션율']::text[] WHERE id = 35;  -- 경직적 물가지수
UPDATE public.words SET meaning = '국제노동기구(ILO)에서는 노동 공급과 수요가 일치하지 않아서 일하고 싶은 욕구가 있음 에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013월', detailed_meaning = '국제노동기구(ILO)에서는 노동 공급과 수요가 일치하지 않아서 일하고 싶은 욕구가 있음 에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013월 10월)한 바 있다. 우리나라 통계청에서도 기존의 공식 실업률만으로는 노동시장을 제대로 반영하는데 한계가 있다고 판단하여 2014년 11월부터 새로운 고용보조지표를 발표하고 있다. 고용보조지표는 실업률을 추계하기 위한 공식적인 실업자 이외에 아르바이트 등 단기근로를 하지만 재취업을 원하는 사람(시간관련 추가취업 가능자), 최근구직활동을 안했을 뿐 취업의사가 있고 취업 가능성이 있는 사람(잠재구직자), 그리고 구직노력을 했으나 육아 등으로 당장 일을 시작하지 못하는 사람(잠재취업가능자) 등을 포함 한다. 여기서 비경제활동인구에 포함된 잠재 취업가능자와 잠재 구직자를 합하여 잠재경제활동인구라고 하고, 이를 기존의 경제활동인구와 합산하여 확장경제활동인구라 한다. 현재 고용보조지표는 그 포괄범위에 따라 세 가지 형태로 작성하여 공표되고 있다. 고용보조지표1은 경제활동인구 대비 기존의 취업자 중 시간관련 추가 취업가능자와 실업자의 비율이며, 고용보조지표2는 실업자와 잠재경제활동인구의 합을 확장경제활동인구로 나누어구한다. 한편 고용보조지표3은 확장경제활동인구 대비 시간관련 추가취업 가능자, 실업자및 잠재경제활동인구를 더한 수치의 비율이다. 최근 발표되고 있는 고용보조지표를 보면기존의 공식 실업률과 상당한 차이를 보이고 있는데, 이는 단시간 근로자가 많거나 취업을 희망하고 있지만 구직활동을 하지 않은 사람 등이 그만큼 많다는 것을 의미한다.', related_words = ARRAY['실업률','잠재경제활동인구']::text[] WHERE id = 40;  -- 고용보조지표
UPDATE public.words SET meaning = '고정금리부채권(Straight Bond)이란 정해진 기일에 고정된 이자를 지급하고 정해진 만기에 원금을 지급하는 가장 일반적인 형태의 채권으로 전환사채(CB; Convertible Bond)의', detailed_meaning = '고정금리부채권(Straight Bond)이란 정해진 기일에 고정된 이자를 지급하고 정해진 만기에 원금을 지급하는 가장 일반적인 형태의 채권으로 전환사채(CB; Convertible Bond)의 주식전환권과 같이 특별한 조건이 없는 채권을 말한다. 회사채, 국채 등 대부분의 채권이 고정금리부로 발행된다. 이에 대비되는 채권으로 변동금리부채권(FRN; Floating Rate Note)이 있다. 이는 정해진 기일에 특정 금리(예: 국내에서는 3개월 CD금리, 해외에서는무위험지표금리(RFR; Risk-Free Rate))에 연동된 금리를 지급하고 정해진 만기에 원금을 지급하는 채권이다. 고정금리부채권에 대한 투자는 향후 금리 하락이 예상될 때 유리하며 금리 상승이 예상될 때에는 변동금리부채권에 투자하는 것이 유리하다. 한편 인플레이션이 심할 때 인플레이션을 헤지하기 위한 목적으로 발행되는 채권이 물가연동채권인데 이 는 원금과 이자가 물가상승률(주로 CPI 사용)에 연동하여 증가한다는 면에서 변동금리부채권과 구별된다.', related_words = ARRAY['변동금리부채권(FRN)']::text[] WHERE id = 42;  -- 고정금리부채권(SB)
UPDATE public.words SET meaning = '환율제도는 고정환율제도(Fixed Exchange Rate System)와 자유변동환율제도(Free Floating Exchange Rate System)를 양극단으로 하여 이를 절충하는 다양한', detailed_meaning = '환율제도는 고정환율제도(Fixed Exchange Rate System)와 자유변동환율제도(Free Floating Exchange Rate System)를 양극단으로 하여 이를 절충하는 다양한 형태로 분류될 수 있다. 고정환율제도는 환율을 정부나 중앙은행이 적정하다고 판단하는 수준으로 일정하게 유지하는 제도이다. 반면 자유변동환율제도는 환율이 외환의 수요와 공급에 의 해 자율적으로 결정되도록 하는 환율제도를 말한다. 고정환율제도는 환율 변동에 따른 충격을 완화하고 거시경제정책의 자율성을 어느 정도 확보할 수 있다는 장점이 있으나 이 를 위해서는 자본이동의 제약이 불가피하여 결과적으로 외화유동성이 부족해질 가능성이 있다. 이 경우 대외불균형이 지속되거나 기초경제여건이 악화되면 환투기공격에 쉽게노출되는 단점이 있다. 반면 자유변동환율제도에서는 자본이동이 자유롭게 이루어지므로 외화유동성 확보가 용이하고 외부충격이 환율 변동에 의해 흡수됨으로써 거시경제정책의 자율적 수행이 수월한 장점이 있다. 다만 외환시장 규모가 작고 외부충격의 흡수 능력이 부족한 신흥국은 환율 변동성의 확대가 경제의 교란 요인으로 작용할 가능성이 크다. 한편 어떤 환율제도를 채택하더라도 ① 통화정책의 자율성 ② 자유로운 자본이동 ③ 환율 안정 등 세 가지 정책목표를 동시에 달성하기는 현실적으로 어려운데, 이를 삼불원칙 (impossible trinity 또는 trilemma)이라고 한다.', related_words = ARRAY['삼불원칙','외환시장']::text[] WHERE id = 45;  -- 고정환율제도/자유변동환율제도
UPDATE public.words SET meaning = '공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다.', detailed_meaning = '공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다. 국방·경찰·소방·공원·도로 등과 같이 정부에 의해서만 공급할 수 있는 것이라든가 또는 정부에 의해서 공급되는 것이 바람직하다고 사회적으로 판단되는 재화 또는 서비스가 이에 해당한다. 공공재에는 보통 시장가격은 존재하지 않으며 수익자부담 원칙도 적용되지 않는다. 따라서 공공재 규모의 결정은 정치기구에 맡길 수밖에 없다. 공공재의 성질로는 어떤 사람의 소비가 다른 사람의 소비를 방해하지 않고 여러 사람이 동시에 편익을 받을 수 있는 비경쟁성·비선택성, 대가를 지급하지 않은 특정 개인을 소비에서 제외하지 않는 비배제성등을 들 수 있다.', related_words = ARRAY['자유재']::text[] WHERE id = 49;  -- 공공재
UPDATE public.words SET meaning = '교환사채(EB; Exchangeable Bond)란 사채권자의 의사에 따라 교환사채 발행기업이 보유하고 있는 타사 주식 등 여타의 유가증권과 교환할 수 있는 선택권이 부여된 사채를 말한다.', detailed_meaning = '교환사채(EB; Exchangeable Bond)란 사채권자의 의사에 따라 교환사채 발행기업이 보유하고 있는 타사 주식 등 여타의 유가증권과 교환할 수 있는 선택권이 부여된 사채를 말한다. 발행하는 채권에 주식이 연계되어 있다는 점에서 발행회사의 신주를 일정한 조건으로 매수할 수 있는 신주인수권부사채(BW; Bonds with Warrant)나, 발행회사의 주식으로 전환할 수 있는 권리가 부여된 전환사채(CB; Convertible Bond) 등과 함께 주식연계증권으로 불린다. 발행회사가 보유하는 교환대상 유가증권은 상장유가증권으로 제한되고 있으며 증권예탁원에 의무적으로 예탁되어야 한다. 발행회사는 낮은 이자율로 사채를 발행하여 금융비용 부담을 덜 수 있어 회사채 발행을 통한 기업자금조달을 촉진할 수 있는 장점이 있다. 반면에 투자자의 입장에서도 비교적 안정적인 데다 미래의 주식가격 상승에 따른 시세차익을 기대할 수 있음에 따라 유리한 투자수단이 된다. 교환이 이루어질때 발행기업의 자산과 부채가 동시에 감소한다. 신규자금 유입이 없다는 점에서 신주인수권부사채(BW)와는 다르고 신주발행에 따른 자본금의 증가가 없다는 점에서 전환사채 (CB)와도 다르다.', related_words = ARRAY['신주인수권부사채(BW)','전환사채(CB)']::text[] WHERE id = 56;  -- 교환사채(EB)
UPDATE public.words SET meaning = '국가경쟁력은 한 나라가 경제성장을 지속하고, 국민들의 삶의 질을 향상시킬 수 있는 능력을 말한다.', detailed_meaning = '국가경쟁력은 한 나라가 경제성장을 지속하고, 국민들의 삶의 질을 향상시킬 수 있는 능력을 말한다. 대표적인 국가경쟁력 지표로 스위스 국제경영개발원(IMD)에서 발표하는 세계경쟁력순위(WCR; World Competitiveness Ranking)가 있다. 국제경영개발원은 기업 활동을 효율적으로 가능하게 하는 제도적ㆍ경제적 조건을 갖추고 있느냐를 국가경쟁력의 핵심으로 보고 주요 통계지표와 기업인 및 연구원 대상 설문조사 결과를 종합하여세계 70여개 국가의 경쟁력을 평가한다. 세계경쟁력순위는 경제 운용 성과, 정부의 효율성, 기업의 경영 효율성, 사회간접자본 등 4개 부문으로 구성되어 있다.', related_words = '{}'::text[] WHERE id = 61;  -- 국가경쟁력
UPDATE public.words SET meaning = '국가의 경제활동도 민간의 경제활동과 마찬가지로 금전 수수를 수반하게 되는데 이와 같은 경제활동에 수반되는 일체의 현금을 통상 국고금이라 한다.', detailed_meaning = '국가의 경제활동도 민간의 경제활동과 마찬가지로 금전 수수를 수반하게 되는데 이와 같은 경제활동에 수반되는 일체의 현금을 통상 국고금이라 한다. 우리나라에서는 국고금의 출납사무를 중앙은행인 한국은행이 담당하고 있다. 그러나 한국은행의 한정된 조직과 인력만으로는 전국의 국고금 납부자에게 충분한 편의를 제공하기 어렵기 때문에 한국은행은 금융기관과의 계약을 통해 금융기관 영업점을 국고 대리점으로 지정하여 국고금 수납사무를 위탁하고 있다. 국고대리점은 국고수납대리점과 국고금수납점으로 구분하는데 기능상 차이는 없으며 계약방식의 차이에 의해서 구분된다. 국고수납대리점은 은행 영업점및 신용협동기구의 중앙회가 이에 해당되며 국고금수납점은 신용협동기구의 중앙회 등이 산하 회원조합(금고)에 국고금 수납사무를 재위탁한 영업점을 말한다. 2025년 6월말 현재국고대리점은 총 16,467개(국고수납대리점 5,647개, 국고금수납점 10,820개)가 있다.', related_words = '{}'::text[] WHERE id = 65;  -- 국고대리점
UPDATE public.words SET meaning = '국민계정은 국민경제의 순환과 변동을 체계적으로 기록한 사회회계로서 경제활동을 거래형태별 및 거래에 참가하는 경제주체별로 파악하여 복식부기 방식으로 기록한 것이다.', detailed_meaning = '국민계정은 국민경제의 순환과 변동을 체계적으로 기록한 사회회계로서 경제활동을 거래형태별 및 거래에 참가하는 경제주체별로 파악하여 복식부기 방식으로 기록한 것이다. 즉, 국민경제의 순환에 따른 변동을 각각의 거래형태와 거래주체 간의 상호연관 하에서 체계적으로 작성한 것이다. 국민계정체계(SNA; System of National Accounts)는 기존의 산업연관표, 국민소득통계, 자금순환표, 국제수지표 등 별개로 파악하고 있던 국민계정관련 통계를 통합, 각종 경제분석에 적합하도록 거래형태 및 거래주체를 경제활동의 동질성에 따라 몇 가지 부문으로 나누어 체계적으로 작성한 것이다. 국민계정체계는 재화와 서비스의 생산 활동을 보여주는 생산계정, 소득의 분배와 사용을 나타내는 소득계정, 비금융자산의 취득과 처분 등을 기록하는 자본계정, 금융 자산 및 부채의 취득과 처분을 기록하는 금융계정, 거주자와 비거주자 간 거래를 기록하는 국외계정, 일정시점에서 경제전체의 자산과 부채 현황을 보여주는 대차대조표계정 등의 기본 체계로 구성된다.', related_words = ARRAY['‌국내총생산(GDP)','산업연관표(I/O Tables)','국민대차대조표','국제수지표']::text[] WHERE id = 71;  -- 국민계정체계(SNA)
UPDATE public.words SET meaning = '국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서', detailed_meaning = '국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세는 포함되지 않는다. 즉 한 나라 국민이 벌어들인순수한 소득을 나타내는 지표로서 다음과 같이 산출한다. 국민소득(NI) = 국민총소득 - 고정자본소모 - 생산 및 수입세 + 보조금= 국민순소득 - 생산 및 수입세 + 보조금= 국민순소득 - 순생산 및 수입세= 피용자보수 + 영업잉여= 임금 + 지대 + 이자 + 이윤', related_words = ARRAY['국민총소득(GNI)']::text[] WHERE id = 74;  -- 국민소득
UPDATE public.words SET meaning = '국민총소득(GNI; Gross National Income)은 한 나라의 국민이 일정 기간 동안 벌어들인임금, 이자, 배당 등의 소득을 모두 합친 것이다.', detailed_meaning = '국민총소득(GNI; Gross National Income)은 한 나라의 국민이 일정 기간 동안 벌어들인임금, 이자, 배당 등의 소득을 모두 합친 것이다. 국가 간에는 재화와 서비스는 물론 노동이나 자본과 같은 생산요소도 활발하게 거래되고 있다. 한 나라의 기업이 다른 나라 사람을 고용하여 생산을 하기도 하고 반대로 그 나라 국민이 다른 나라에 나가 생산활동에 참여하기도 한다. 여기서 생산요소의 국가 간 이동을 고려하여 거주성 측면, 즉 한 나라의 국민을 기준으로 소득을 측정한 것이 국민총소득이다. 국민총소득(명목기준)은 GDP(명목기준) 에다 한 나라의 국민(거주자)이 다른 나라에서 벌어들인 소득(국외수취요소소득)을 더하고, 다른 나라 국민(비거주자)이 그 나라에서 벌어들인 소득(국외지급요소소득)을 뺀 금액이다. 다시 말해서 국민총소득(명목기준)은 GDP에 국외순수취요소소득을 더하여 산출된다. 다 만 실질기준 국민총소득은 실질구매력을 반영하기 위하여 실질GDP에다 국외순수취요소소득뿐만 아니라 교역조건 변화에 따른 실질무역손익까지 고려하여 산출한다. 국민총소득에서 고정자본소모를 제외하면 국민순소득(NNI; Net National Income)이 된다.', related_words = ARRAY['국내총생산(GDP)','국외순수취요소소득']::text[] WHERE id = 77;  -- 국민총소득(GNI)
UPDATE public.words SET meaning = '특정 국가나 지역이 국제금융시장으로 기능하기 위해서는 자국 통화의 국제통용성, 상대적으로 우월한 기초경제력, 고도로 발달된 금융시장과 다양한 장단기 금융수단의 자유로 운 거래, 전 세계시장 정보의', detailed_meaning = '특정 국가나 지역이 국제금융시장으로 기능하기 위해서는 자국 통화의 국제통용성, 상대적으로 우월한 기초경제력, 고도로 발달된 금융시장과 다양한 장단기 금융수단의 자유로 운 거래, 전 세계시장 정보의 신속 저렴한 공급, 세계적인 상품 및 서비스거래의 중심지등의 요건을 두루 갖추어야 한다. 국제금융중심지는 이러한 국제금융시장의 요건을 갖추고 있어 세계적 금융기관들이 본점, 지점, 현지법인의 형태로 영업망을 집중시킴으로써대량의 국제금융거래가 지속적, 반복적으로 이루어지는 장소를 말한다. 대표적인 국제금융중심지로는 뉴욕, 런던, 동경 등이 있다. 한편 역외 국제금융중심지는 주로 비거주자로 부터 자금을 조달하여 비거주자를 대상으로 운영되는 금융중개시장으로, 조세 및 금융규제 면에서 특혜를 부여하여 인위적으로 창설한 금융 중심지이다. 홍콩, 싱가포르, 룩셈부르크 등이 대표적이다.', related_words = ARRAY['국제금융시장']::text[] WHERE id = 82;  -- 국제금융중심지
UPDATE public.words SET meaning = '원유는 전세계적으로 수백 종이 거래되고 있다.', detailed_meaning = '원유는 전세계적으로 수백 종이 거래되고 있다. 이중 국제원유시장의 대표 유종은 미국 서부텍사스유(WTI; West Texas Intermediate), 영국 브렌트유 및 아랍에미레이트 (UAE) 두바이유의 세 가지이다. WTI는 북미, 브렌트유는 유럽 및 아프리카, 두바이유는 중동을 각각 대표하는 기준유가를 정하는 유종으로 사용되고 있다. 국제원유가격은 1980 년대 중반까지는 석유수출국기구(OPEC; Organization of the Petroleum Exporting Countries)의 발표가격을 기준으로 사용하였다. 그러나 석유파동 등으로 인한 국제원유가격의 변동성을 회피하기 위해 선물거래가 활성화되면서 선물가격이 실질적인 현물유가 의 기준역할을 하게 되었다. 우리나라에서는 수입 비중이 높은 두바이유의 가격이 원유도 입단가에 큰 영향을 미친다. 국제석유시장에서는 선물시장 거래량이 가장 많고 광범위한 지역으로 수출되는 브렌트유의 가격이 가장 높은 대표성을 갖고 있다. 국제원유가격은 장기적으로 원유 수요와 공급에 의해 결정되나 원유 공급지의 지정학적 리스크와 기상, 미달러화 가치, 주요국 석유재고의 변동 등 많은 요인의 영향을 받는다.', related_words = ARRAY['선물거래']::text[] WHERE id = 86;  -- 국제원유가격
UPDATE public.words SET meaning = '국제투자대조표(IIP; International Investment Position)는 일정 시점 현재 한 나라 거주자의 비거주자에 대한 금융자산(대외투자) 및 금융부채(외국인투자) 잔액을 기록한', detailed_meaning = '국제투자대조표(IIP; International Investment Position)는 일정 시점 현재 한 나라 거주자의 비거주자에 대한 금융자산(대외투자) 및 금융부채(외국인투자) 잔액을 기록한 통계표로서 국제수지의 금융계정(직접투자, 증권투자, 파생금융상품, 기타투자, 준비자산) 과 포괄범위가 동일하다. 일정 시점의 대외금융자산/부채 잔액은 거래일 이후 환율이나 주가변동 등으로 인한 가치평가분이 포함되어 있기 때문에 금융계정의 거래 누계액과 차이가 있을 수 있다. 한편 국제투자대조표의 대외금융자산/부채에서 지분성투자(직접투자내 지분투자, 증권투자 내 지분증권, 기타투자 내 기타지분)와 파생금융상품을 제외할 경우 대외채권·채무 통계와 개념적으로 일치한다. 국제투자대조표는 한국은행에서 매분기작성하여 발표하고 있다.', related_words = ARRAY['국제수지(BOP)']::text[] WHERE id = 90;  -- 국제투자대조표(IIP)
UPDATE public.words SET meaning = '일반적인 경우 기업이 재화 및 서비스 생산량을 늘려감에 따라 추가적으로 소요되는 평균생산비용도 점차 늘어난다.', detailed_meaning = '일반적인 경우 기업이 재화 및 서비스 생산량을 늘려감에 따라 추가적으로 소요되는 평균생산비용도 점차 늘어난다. 그런데 일부 재화 및 서비스 생산의 경우에는 생산량이 늘어날수록 평균비용이 감소하는 현상이 나타나는데 이를 규모의 경제(Economies of Scale) 라고 한다. 이런 현상은 초기 생산단계에서 시설투자나 연구개발 비용, 인프라 확장 등으로 막대한 투자비용이 필요하지만 생산과정의 표준화, 생산효율성 증대, 대량 생산 등으로 생산과정에서는 큰 비용이 들지 않는 반도체, 자동차, 항공기, 철강, 석유화학, 유통 및 물류 등의 산업에서 흔히 나타난다. 또한 사용자가 많을수록 가치가 높아지는 플랫폼 비즈니스나 통신망 등 네트워크 효과가 발생하는 산업에도 규모의 경제가 존재한다.', related_words = ARRAY['범위의 경제']::text[] WHERE id = 94;  -- 규모의 경제
UPDATE public.words SET meaning = '금리선물(Interest Rate Futures)이란 기초자산인 금리를 거래대상으로 하며 현재의 시점에서 정한 가격으로 미래의 특정 시점에서 사거나 팔 것을 약정하는 계약을 말하다.', detailed_meaning = '금리선물(Interest Rate Futures)이란 기초자산인 금리를 거래대상으로 하며 현재의 시점에서 정한 가격으로 미래의 특정 시점에서 사거나 팔 것을 약정하는 계약을 말하다. 금리선물의 대표적인 상품은 기초자산별로 다양한 만기의 국채선물이다. 3년 국채선물의 주요 내용을 보면 다음과 같다. 기초자산은 최종결제일 현재 만기 3년, 액면금액 1억원, 표면금리 5%, 반기별로 이자를 지급하는 가상의 국고채권이다. 가격의 표시방법은 액면금액 1억원을 100으로 환산하여 소수점 둘째자리까지 표시한다. 최소가격 변동폭인 1tick의 크기는 0.01인데 그 가치는 가상채권 가격으로는 10,000원에 해당되며 국고채금리 1bp(0.01%)는 국채선물가격 3tick과 거의 동일하다. 투자자들은 금리변동위험 헤지(hedge) 및 투기적 목적으로 국채선물을 거래한다. 일반적으로 은행, 보험사 등 기관투자가들은 현물채권을 다량으로 보유하고 있으므로 향후 시장금리가 상승하면 채권가격이 하락하는 금리위험에 노출되어 있다. 이런 위험을 회피하기 위해 국채선물을 매도(시장금리 상승에 따른 보유채권의 가격 하락이 국채선물 매도에 따른 이익으로 상쇄)하게되는데 이를 헤지거래라고 한다. 반면 보유채권 없이 국채선물가격의 방향을 예측하고 이 를 바탕으로 국채선물을 매수 또는 매도하여 이익을 추구하는 거래를 할 수 있는데 이를 투기적 거래라고 한다. 국채선물의 경우 거래증거금률이 매우 낮아(3년 만기, 0.5%) 레버리지가 매우 높으므로 헤지펀드 등 외국인들이 이런 투기적 거래를 많이 이용하고 있으며 국채선물가격에 미치는 영향도 상당히 크다. 한편 금리선물시장에서의 가격 움직임을 보고 향후 시장금리가 어떤 방향으로 움직일 것인지를 예측하기도 하는데 특히 미국의 페더럴펀드금리선물(federal funds futures)은 시장참가자들에게 향후 미연준이 통화정책을 어떤 방향으로 운용할 것인지를 가늠해 볼 수 있는 지표역할을 하기도 한다.', related_words = '{}'::text[] WHERE id = 104;  -- 금리선물
UPDATE public.words SET meaning = '금리자유화란 금리규제를 철폐함으로써 금리가 시장의 자금수급에 따라 자유로이 결정될수 있도록 하는 조치이다.', detailed_meaning = '금리자유화란 금리규제를 철폐함으로써 금리가 시장의 자금수급에 따라 자유로이 결정될수 있도록 하는 조치이다. 금융시장의 대표적인 가격변수인 금리를 제한하는 것은 역사적으로 보아 미국 등 다수의 국가에서 금융불안이 반복적으로 발생함에 따라 금융안정을 도 모하기 위해 도입한 금융규제의 하나이다. 이러한 구조적 금융규제로는 금리규제 이외에 업무영역규제, 진입제한 등이 있다. 그러나 1970~80년대 인플레이션이 심화되면서 은행의 자금중개가 위축되는 이른바 디스인터미디에이션(disintermediation)이 발생하는 가 운데 금융규제를 우회하는 금융혁신이 진전되고 금융자유화가 추진되면서 각국은 금리규제를 단계적으로 철폐하였다. 대표적으로 미국의 경우 ‘레귤레이션 큐(Q)’라는 연준 규정에 의해 은행예금 최고금리가 제한되었는데, 1980년대 일련의 자유화조치 등으로 금리자유화가 진전되었다. 한국은 금융기관 간 경쟁을 촉진함으로써 금융의 효율성을 높이고 금융산업의 대외경쟁력을 강화하기 위하여 1991년 8월 수립된 “4단계 금리자유화 추진계획”에 따라 1995년 11월 제3단계 금리자유화를 완결하였다. 이어 2004년 2월부터는 요구불예금 금리도 자유화함에 따라 모든 예금의 금리상한 규제가 폐지되었다. 우리나라의 경우 금융부문 낙후의 주요 원인이 금리의 가격기능 위축에 있다는 점에서 금리자유화는 시장원리에 의한 경제운용과 통화정책의 유효성 제고를 위한 기반이 되었다.', related_words = '{}'::text[] WHERE id = 106;  -- 금리자유화
UPDATE public.words SET meaning = '금융이해력은 재무적 자원을 효과적으로 관리하고 생애 전반에 걸쳐 재정적 안정을 확보하기 위해 필요한 금융 지식, 기술, 태도 등을 포괄하는 능력을 의미한다.', detailed_meaning = '금융이해력은 재무적 자원을 효과적으로 관리하고 생애 전반에 걸쳐 재정적 안정을 확보하기 위해 필요한 금융 지식, 기술, 태도 등을 포괄하는 능력을 의미한다. 이는 금융 정보를 이해하고 활용하여 합리적인 금융 결정을 내리고, 자신의 재무 목표를 달성하는 데 필요한 역량을 말한다. 일반적으로 금융이해력은 금융지식, 금융행위, 금융태도와 같은 요 소들을 포괄한다. 금융 지식은 금융 상품, 시장, 서비스 등에 대한 기본적인 이해력을 말한다. 금융 행위는 예산 관리, 저축, 투자, 신용 관리 등 실제 금융 활동을 효과적으로 수행하는 능력을 말한다. 금융 태도는 미래를 위한 계획, 위험 감수, 소비 습관 등 금융 의사결정에 영향을 미치는 태도를 의미한다. 이러한 금융이해력은 개인의 재정적 안정뿐만 아니라 사회 전체의 경제적 복지에도 영향을 미치기 때문에 금융교육을 통해 금융이해력을 높이는 것이 매우 중요하다. 이와 관련해 한국은행과 금융감독원은 2012년부터 OECD INFE(International Network on Financial Education) 가이드 라인을 바탕으로 한 ‘전국민 금융이해력 조사’를 공동 실시하고 있다.', related_words = ARRAY['금융 지식','금융 행위','금융 태도','디지털 금융이해력']::text[] WHERE id = 123;  -- 금융이해력
UPDATE public.words SET meaning = '금융채는 은행, 금융투자회사, 리스회사, 신용카드회사 등 금융기관이 장기적으로 안정적인 자금을 조달하기 위하여 발행하는 채권을 말한다.', detailed_meaning = '금융채는 은행, 금융투자회사, 리스회사, 신용카드회사 등 금융기관이 장기적으로 안정적인 자금을 조달하기 위하여 발행하는 채권을 말한다. 예를 들면, 은행채는 「은행법」에 근거하여 은행이 자기자본의 5배 이내에서 발행할 수 있으며, 산업금융채권의 경우 「한국산업은행법」에 근거하여 한국산업은행이 자본금 및 적립금의 30배 이내에서 발행할 수있다. 중소기업금융채권은 기업은행이 「중소기업은행법」에 근거하여 자본금 및 적립금의 20배 이내에서 발행할 수 있다. 금융채는 채권의 성격에 따라 일반채권, 후순위채권, 하이 브리드채권(신종자본증권), 기타 주식관련 사채, 옵션부채권 등으로 구분된다. 금융기관은 금융채를 발행하여 조달한 자금을 주로 장기 산업자금으로 대출한다. 한편 금융채 금리는 은행의 대출금리와도 관련이 있다. 금융채 금리는 단독으로 은행 대출금리의 준거금리가 되기도 하고 자금조달비용지수(COFIX; Cost of Funds Index) 산정시 예금금리, CD금리 등과 함께 가중평균되어 반영되기도 한다.', related_words = ARRAY['자금조달비용지수(COFIX)']::text[] WHERE id = 127;  -- 금융채
UPDATE public.words SET meaning = '기념화폐는 국가적 행사, 역사적 사건, 중요한 인물 또는 국가유산 등을 기념하기 위해 특별히 발행되는 화폐로서 유통 목적으로 발행되는 통용 화폐와 달리, 주로 수집 가치와 기념적 의미를 지니며', detailed_meaning = '기념화폐는 국가적 행사, 역사적 사건, 중요한 인물 또는 국가유산 등을 기념하기 위해 특별히 발행되는 화폐로서 유통 목적으로 발행되는 통용 화폐와 달리, 주로 수집 가치와 기념적 의미를 지니며 액면가보다 높은 가격에 판매되는 경우가 많다.우리나라에서는 기념화폐가 주화로 발행되는 경우 ‘기념주화’, 지폐로 발행되는 경우 ‘기념은행권’이라 한다. 한국은행은 1971년 우리나라 최초의 기념주화인 ‘대한민국 반만년역사’를 시작으로, 서울올림픽대회, 정부수립 50주년, 서울 G20 정상회의 개최 등 국가적행사와 전통민속놀이, 한국의 문화유산, 한국의 국립공원 등 다양한 주제를 담은 기념주화를 발행해 왔다. 한편, 기념은행권은 평창동계올림픽 개최 기념으로 최초의 액면 2000 원 기념은행권이 발행된 바 있다.', related_words = ARRAY['화폐 발행','화폐의 액면체계']::text[] WHERE id = 131;  -- 기념화폐
UPDATE public.words SET meaning = '기준순환일이란 경기변동 과정에서 국면전환이 이루어진 일자를 의미한다.', detailed_meaning = '기준순환일이란 경기변동 과정에서 국면전환이 이루어진 일자를 의미한다. 즉 경기가 확장국면에서 수축국면으로 전환하는 경기정점 또는 수축국면에서 확장국면으로 전환하는 경기저점의 구체적인 일자를 말한다. 경기변동은 이론적이고 추상적인 개념이기 때문에 현실적으로는 생산, 소비, 투자, 고용 등 경기변동 상황을 비교적 잘 반영하는 여러 지표를 통계적으로 가공한 후 그 움직임을 파악하여 판단한다. 그러나 이러한 경기변동의 실증적 연구는 분석 방법에 따라 결과가 다양하게 나오는 경우가 일반적이다. 이러한 점을 고려하여 각국의 통계 당국은 여러 측면을 살펴보고 하나의 기준순환일을 공식적으로 정하고 있다. 우리나라에서는 통계청이 기준순환일을 월 단위로 발표하고 있다. 기준순환일은 경기변동이라는 추상적 개념을 현실적인 경제의 움직임과 구체적으로 연결시켜주는 매우 중요한 고리의 역할을 한다. 기준순환일이란 용어가 언제부터 쓰이게 되었는지는 분명하지 않으나 문헌상으로는 1940~50년대 미국경제연구소(NBER; National Bureau of Economic Research)에서 발간한 경기변동관련 연구로부터 유래한 것으로 추정된다.', related_words = ARRAY['경기','경기종합지수','동행종합지수']::text[] WHERE id = 143;  -- 기준순환일
UPDATE public.words SET meaning = '긴급수입제한조치(Safeguard) 즉, 세이프가드란 특정 품목의 수입이 급증하여 국내 업체에 심각한 피해가 발생하거나 그럴 우려가 있을 경우, 수입국이 관세 인상이나 수입량 제한 등을 통해', detailed_meaning = '긴급수입제한조치(Safeguard) 즉, 세이프가드란 특정 품목의 수입이 급증하여 국내 업체에 심각한 피해가 발생하거나 그럴 우려가 있을 경우, 수입국이 관세 인상이나 수입량 제한 등을 통해 수입품에 대한 규제를 할 수 있는 제도이며 무역장벽의 하나라고 볼 수 있다. 현재 세계무역기구(WTO; World Trade Organization)는 가입국들이 긴급수입제한 조치를 실행할 권리를 인정하고 있다. 수입물품에 대한 수량제한, 관세율 조정 및 국내산업의 구조조정을 촉진하기 위한 지원정책 등이 세이프가드로 동원될 수 있다. 그러나 세계무역기구의 세이프가드 협정은 제한적으로 취해져야 하고 세이프가드를 실시하는 수입국은 해당 물품의 수출국에 적절한 보상을 해줄 것을 권고하고 있다.', related_words = ARRAY['상계관세','슈퍼301조']::text[] WHERE id = 151;  -- 긴급수입제한조치
UPDATE public.words SET meaning = '범죄학의 낙인이론에 따르면 일탈 또는 범죄 행동은 관련 주체의 독자적 행동에 의해서도 발생하지만, 해당 행동에 대한 사회적 평가 또는 해당 행동을 한 주체의 사회적 소외의 결과로도 발생할 수 있다.', detailed_meaning = '범죄학의 낙인이론에 따르면 일탈 또는 범죄 행동은 관련 주체의 독자적 행동에 의해서도 발생하지만, 해당 행동에 대한 사회적 평가 또는 해당 행동을 한 주체의 사회적 소외의 결과로도 발생할 수 있다. 어떤 사람이 실수나 불가피한 상황에 의해 사회적으로 바람직하지 못한 행위를 한 번 저지르고 이로 인해 나쁜 사람으로 낙인찍히면 그 사람에 대한 부정적 인식이 형성되고 이 인식은 쉽게 사라지지 않는다. 이로 인해 추후 어떤 상황이 발생했을 때 해당 사람에 대한 부정적 사회인식 때문에 유독 그 사람에게 상황이 부정적으로 전개되어 실제로 일탈 또는 범죄행위가 저질러지는 현상을 낳는데, 이를 낙인효과라고 한 다. 경제 분야에서도 이러한 현상이 발생한다. 예를 들어, 과거에 한 번 부도를 일으킨 기업이나 국가의 경우 이후 건전성을 회복했다 하더라도 시장의 충분한 신뢰를 얻기 어려워지며, 나아가 신용위기가 발생할 경우 투자자들이 다른 기업이나 국가보다 해당 기업이나 국가를 덜 신뢰하여 투자자금을 더 빨리 회수하고 이로 인해 실제로 해당 기업이나 국가 가 위기에 빠질 수 있다.', related_words = '{}'::text[] WHERE id = 155;  -- 낙인효과
UPDATE public.words SET meaning = '주택담보대출 취급 시 담보가치(주택가격) 대비 대출 취급 가능금액의 비율 (Loan-To- Value ratio)을 의미한다.', detailed_meaning = '주택담보대출 취급 시 담보가치(주택가격) 대비 대출 취급 가능금액의 비율 (Loan-To- Value ratio)을 의미한다. 예를 들어 아파트 감정가격이 5억원이고 담보인정비율(LTV)이 70%이면 금융기관으로부터 3억 5천만원의 주택담보대출을 받을 수 있다. 「은행업감독업무시행세칙」에서는 “담보인정비율 = [(담보대출금액+선순위채권+임차보증금 및 최우선변제 소액임차보증금)/담보가치×100” 방식으로 산정하도록 하고 있다. 여기서 담보가치는 ① 국세청의 기준시가 ② 감정평가법인 등의 감정평가액 ③ 한국부동산원의 층별ㆍ호별 격차율 지수로 산정한 가격 ④ KB부동산시세의 ‘일반평균가’ 중 금융기관 자율로 선택하여 적용한다. 당초 LTV 규제는 은행권을 중심으로 내규에 반영하여 자율적으로 시행해 오다가 금융기관의 경영 안정성 유지, 부동산 투기 억제 등을 위한 주택담보대출 규모의 관리 필요성이 제기되면서 2002년 9월 감독규제 수단으로 도입되었다. 이후 가계부채증가 억제 및 부동산경기 조절 등 거시건전성정책 수단으로 활용되고 있으며, 주택 소재지(규제·비규제), 차주 특성(무주택·다주택·생애최초 등) 및 대출목적(주택구입·임대사업등)별로 세분화하여 차등 적용되고 있다. 한편, 금융기관은 주택담보대출 취급시 담보인정비율(LTV)과 함께 차주의 부채상환능력을 나타내는 총부채상환비율(DTI), 총부채원리금상환비율(DSR) 등도 고려하여 대출규모를 결정한다.', related_words = ARRAY['총부채상환비율(DTI)','총부채원리금상환비율(DSR)']::text[] WHERE id = 170;  -- 담보인정비율(LTV)
UPDATE public.words SET meaning = '도덕적 해이는 거래당사자의 한쪽이 상대보다 양질의 정보를 더 많이 가지고 있는 상태 (정보의 비대칭성)에서 계약이 이루어진 후에 나타날 수 있는 문제이다.', detailed_meaning = '도덕적 해이는 거래당사자의 한쪽이 상대보다 양질의 정보를 더 많이 가지고 있는 상태 (정보의 비대칭성)에서 계약이 이루어진 후에 나타날 수 있는 문제이다. 예를 들면 주주와 전문경영인, 은행과 차입자 간의 계약을 들 수 있다. 전문경영인은 회사의 경영상황에 대해 주주보다 더 많은 정보를 가지고 주주가 아닌 자신의 이익을 극대화하는 경우가 있을 수 있다. 이를 전문경영인의 도덕적 해이라 한다. 또한 은행으로부터 대출을 받은 차입자가 계약대로 차입금을 적절한 투자에 사용하는지를 은행이 정확히 확인할 수 없기때문에 발생하는 문제는 차입자의 도덕적 해이에 해당한다. 도덕적 해이를 해결하기 위해서는 정보의 비대칭성을 완화하거나, 전문경영인이나 차입자(대리인)의 이해를 주주나 은행(주인)의 이해와 일치시키는 장치를 마련하는 게 중요하다. 여기서 주인과 대리인의 이해가 일치하지 않아 발생하는 문제를 주인-대리인 문제 또는 대리인 문제라고 한 다. 한편 정보의 비대칭성 상태에서 계약이 이루어지기 전에 나타날 수 있는 문제로는 역선택이 있다.', related_words = ARRAY['역선택','정보의 비대칭성']::text[] WHERE id = 181;  -- 도덕적 해이
UPDATE public.words SET meaning = '레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다.', detailed_meaning = '레버리지비율(Leverage Ratio)은 ‘[기본자본(Tier 1) / 총익스포저(난외자산 포함)] × 100’으로 정의된다. 분자의 자본은 바젤Ⅲ 기준 기본자본(Tier 1)을 사용하며 분모의 총익스포저는 자기자본비율을 산정할 경우에 적용되는 위험가중자산과는 달리 명목가액을 기준으로 하여 산출한다. 자기자본비율 규제 하에서 은행은 호황기에 보유자산의 위험가 중치를 낮게 설정함으로써 외형상 높은 자기자본 수준을 유지하면서 레버리지를 확대할수 있었다. 이 경우 위기 발생시 급격한 디레버리징(자산처분, 부채상환)이 발생하여 위기가 증폭되는 악순환이 발생할 수 있는데, 레버리지비율 규제는 이러한 자기자본비율 규제의 문제점을 보완한다고 할 수 있다. 바젤은행감독위원회(BCBS)는 2015년 1월부터 레버리지비율 공시를 의무화하였으며 은행들은 2018년 1월부터 최저 레버리지비율(3%)도 준수해야 한다. 이 밖에도 글로벌 시스템적 중요 은행(G-SIB)에게는 2022년 1월부터 시스템적중요도에 따라 국별로 추가 레버리지비율이 적용되고 있다. 이는 위험가중자산 기반 자기자본비율 규제에서 G-SIB에 대해 부과하고 있는 추가자본 규제와의 일관성을 갖추기 위한 것으로 G-SIB은 자기자본비율 규제상 부과되는 추가자본의 50%만큼 상향 조정된 레버리지비율을 준수해야 한다. 예를 들어 2%의 추가자본이 부과된 G-SIB이 준수해야 할레버리지비율은 최저 레버리지비율 3%에 추가자본의 50%에 해당하는 1%가 가산된 4% 가 된다. G-SIB이 동 레버리지비율을 준수하지 못할 경우, 추가자본의 미준수시와 동일하게 이익배분이 제한된다. 우리나라는 레버리지비율을 「은행업감독규정」에서 단순기본자본비율로 정의하고 있으며 2015년 1분기부터 보조지표로 공시된 후 2018년부터 동 규제(3% 이상)가 시행되었으며 2020년 1월부터는 인터넷전문은행에도 적용되었다.', related_words = ARRAY['기본자본(Tier 1)','익스포저','디레버리징']::text[] WHERE id = 195;  -- 레버리지비율/단순기본자본비율
UPDATE public.words SET meaning = '로보어드바이저(Robo-Advisor)는 로봇(robot)과 자문가(advisor)의 합성어이다.', detailed_meaning = '로보어드바이저(Robo-Advisor)는 로봇(robot)과 자문가(advisor)의 합성어이다. 이는 인공지능 알고리즘, 빅데이터 등을 활용하여 투자자의 투자성향·리스크 선호도·목표수익률 등을 분석하고 그 결과를 바탕으로 투자자문·자산운용 등 온라인 자산관리서비스를 제공하는 것이다. 서비스 제공 과정에서 비용으로 작용하는 사람의 개입을 최소화함으로써기존 자산관리서비스보다 더 낮은 최소투자금액과 더 싼 수수료로 소액 자산을 가진 일반개인도 더 쉽게 접근할 수 있게 되었다.', related_words = ARRAY['빅데이터','상장지수펀드(ETF)']::text[] WHERE id = 197;  -- 로보어드바이저
UPDATE public.words SET meaning = '명목국내총생산(Nominal GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 그 생산물이 생산된 기간의 가격을 적용하여 계산한 것이다.', detailed_meaning = '명목국내총생산(Nominal GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 그 생산물이 생산된 기간의 가격을 적용하여 계산한 것이다. 명목GDP의 변동분에는 최종생산물의 수량과 가격변동분이 혼재되어 있다. 명목GDP는 경제규모 등의 파악에 이용된다. 반면 실질국내총생산(Real GDP)은 한 나라 안에서 생산된 최종생산물의 가치를 기준년도 의 가격으로 측정한 것이다. 실질GDP는 우리나라를 비롯한 많은 국가에서 UN이 권고한 국제기준인 국민계정체계(SNA; System of National Accounts)에 따라 연쇄가중법에 의 해 추계되고 있다. 연쇄가중법은 기준연도의 가중치를 계속 적용하지 않고 기준연도의 명목금액에 연쇄물량지수를 곱하여 실질GDP를 산출한다. 실질GDP는 경제성장, 경기변동등 전반적인 경제활동의 흐름을 분석하는 데 이용된다. 명목GDP는 특정 시점의 국가간비교, 다른 지표의 기준치(예: 총저축률, GDP대비 경상수지 비율 등)로 활용된다.', related_words = ARRAY['연쇄가중법','계절변동조정시계열','경제성장률']::text[] WHERE id = 210;  -- 명목국내총생산/실질국내총생산
UPDATE public.words SET meaning = '모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 이용하여 무선인터넷을 통하여금융기관에 접속하여 이용할 수 있는 금융서비스이다.', detailed_meaning = '모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 이용하여 무선인터넷을 통하여금융기관에 접속하여 이용할 수 있는 금융서비스이다. 이 서비스는 은행이 이동통신회사의 무선인터넷망을 통해 고객의 자금이체 및 계좌조회 등 금융거래과정 전반을 관리하는 것을 기본구조로 하고 있다. 1999년 농협은행 등이 제공하기 시작한 국내 모바일뱅킹 서 비스는 2009년 스마트폰 기반 모바일뱅킹 서비스가 개시된 이후에는 주로 스마트폰을 통해 제공되고 있다. 모바일뱅킹을 통해 제공되고 있는 서비스에는 예금조회, 거래명세조회, 자금이체 등이 있으며, 일부 은행에서는 현금서비스, 대출, 환율조회, 수표조회, 사고 신고 등의 서비스까지 제공하고 있다. 모바일뱅킹 서비스는 대부분의 국내은행 및 우체국, 신용협동조합 및 새마을금고중앙회 등에서 제공되고 있다.', related_words = ARRAY['인터넷뱅킹','텔레뱅킹(폰뱅킹)']::text[] WHERE id = 214;  -- 모바일뱅킹
UPDATE public.words SET meaning = '배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다.', detailed_meaning = '배당할인모형(Dividend Discount Model)은 주식투자에 따라 발생하는 미래의 현금흐름을 적절한 할인율을 적용하여 현재가치로 전환함으로써 주식의 현재가치를 평가하는 모형이다. 주식투자에 따른 현금흐름은 보유기간 중의 배당금과 매도할 경우의 주식가격으로 구성되는데 만일 보유기간이 매우 길다면 매도할 주식가격의 현재가치는 0에 수렴하게 된다. 일반적으로 주식은 만기가 없는 영구적인 증권이므로 보유기간을 무한대로 상정할 수 있다. 따라서 주식의 가치는 각 기별 배당금을 적절한 할인율(주식투자의 요 구수익률이라고 함)로 할인한 현재가치의 합으로 볼 수 있다. 배당할인모형은 주식가치평가모형 중 가장 기본적인 모형으로서 주식가격 형성에 있어서 핵심 요인이 무엇인지를 보여준다. 그러나 기업경영 및 이익에 관한 수많은 불확실성 등으로 인해 먼 미래의 배당금을 추정하는 것은 불가능에 가깝다. 이러한 문제점을 극복하기 위해 Myron Gordon은 배당금이 일정률로 성장한다는 가정을 기초로 정률성장배당할인모형(Constant Growth Dividend Discount Model)을 제시하였다. Gordon의 모형에 따르면 현재 주식의 가치 (P0), 최근 예상배당(D1), 주식투자의 요구수익률(r), 배당성장률(g) 간에는 P0=D1/(r-g) 의 관계가 성립한다.', related_words = ARRAY['배당금','할인율']::text[] WHERE id = 231;  -- 배당할인모형
UPDATE public.words SET meaning = '베버리지곡선(Beveridge Curve)은 노동 공급(실업률) 및 수요(빈일자리율) 간 관계를 나 타내는 곡선으로 이를 통하여 노동수급 상황과 노동시장의 효율성 정도를 파악할 수 있다.', detailed_meaning = '베버리지곡선(Beveridge Curve)은 노동 공급(실업률) 및 수요(빈일자리율) 간 관계를 나 타내는 곡선으로 이를 통하여 노동수급 상황과 노동시장의 효율성 정도를 파악할 수 있다. 실업과 빈일자리 간 미스매치를 언급한 영국 경제학자 베버리지(W. Beveridge)를 따라서 명명된 베버리지곡선은 통상 실업률이 높아지면 빈일자리율이 줄어들고, 실업률이 낮아지면 빈일자리율은 늘어나는 관계가 있다. 이는 실업률을 X축, 빈일자리율을 Y축으로 할 때, 경기 확장기에서처럼 유휴노동력이 축소되면 실업율이 줄어들고 빈일자리율은 늘어나며, 경기 수축기에서 나타나듯이 유후노동력이 늘어나면 실업률이 늘어나고 빈일자리율은 줄어드는 특성에 기인한다. 한편 노동시장 내 마찰적 요인의 증가로 구인·구직자 간 매칭 효율성이 낮아질 경우 실업률과 빈일자리율이 동시에 높아져 곡선 자체가 오른쪽 상방으로 이동할 수 있다.', related_words = '{}'::text[] WHERE id = 236;  -- 베버리지곡선
UPDATE public.words SET meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한', detailed_meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 기본자본에 비해 손실흡수능력이 떨어지지만 예상외 손실로 은행이 파산할 경우예금자를 포함한 일반채권자에 앞서 손실을 흡수(혹은 은행의 청산 시 은행의 손실을 보전)할 수 있는 자기자본(gone-concern capital)을 의미한다. 보완자본은 해당하는 요건을 충족하는 보완자본증권 및 이와 관련된 자본잉여금, 자회사가 발행한 보완자본증권의 일부 제3자 보유분, 특정 요건을 충족하는 대손충당금 등으로 구성된다. 해당 은행이 발행한 증권이 보완자본증권으로 인정받기 위해서는 예금자·일반채권자보다 후순위일 것,최저만기 5년 이상이고 금리 상향조정을 비롯한 중도상환 유인이 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3). 아울러 신용리스크 측정시 표준방법을 사용하는 은행이 설정한 일반 대손충당금(general provisions)과 내부등급법 사용은행이 예상손실을 초과하여 적립한 적격 대손충당금은 규제자본과 동일하게 예상외 손실을 흡수하는 데 사용할 수 있다고 간주하여 일정 범위(각각 신용위험가중자산의 1.25% 및 0.6%) 내에서 보완자본(supplementary capital)에 가산할 수 있다.', related_words = ARRAY['BIS 자기자본비율','기본자본(Tier 1)']::text[] WHERE id = 240;  -- 보완자본(Tier 2)
UPDATE public.words SET meaning = '부가가치기준 무역(TiVA; Trade in Value Added)은 국가간 거래를 재화와 서비스의 각생산 단계에서 창출된 부가가치를 기준으로 파악하는 경제통계이다.', detailed_meaning = '부가가치기준 무역(TiVA; Trade in Value Added)은 국가간 거래를 재화와 서비스의 각생산 단계에서 창출된 부가가치를 기준으로 파악하는 경제통계이다. 최근 글로벌 공급망 (Global Value Chain)이 복잡해지면서 한 제품이 여러 국가의 부품, 설계, 생산과정을 거쳐 완성되고 있다. 따라서 재화와 서비스를 최종 수출 국가 몫으로만 기록(gross value)하는 기존 통계로는 교역이 각국의 경제에 미치는 영향을 분석하는 데 한계가 있다. 전통적인 무역통계는 중간재 거래액이 중복계상(double-counting)되고, 실제로 중간재를 생산하고 가치 창출에 기여한 국가들의 기여도가 정확히 반영되지 않는다. 이에 반해 부가가 치기준의 무역(TiVA)은 상대국 최종수요로 인해 자국에서 창출되는 부가가치의 이입액 (VA-in: 무역통계의 수출과 대응)과 자국의 최종수요로 인해 상대국에서 창출되는 부가 가치의 이출액(VA-out: 무역통계의 수입과 대응)으로 정의한다. 부가가치기준의 무역은 무역 구조를 보다 정확하고 투명하게 파악할 수 있어 국가별 경쟁력 분석, 산업정책 수립, 국제 협상 전략 등에 중요한 기초자료이다. 한편, 부가가치기준 무역은 산업간 거래관계를 통해 상호 의존관계를 분석하는 산업연관분석의 원리를 적용한 국제산업연관표를 활용하여 측정할 수 있다.', related_words = ARRAY['산업연관표(I/O Tables)']::text[] WHERE id = 250;  -- 부가가치기준 무역(TiVA)
UPDATE public.words SET meaning = 'CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을 기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한', detailed_meaning = 'CDO(Collateralized Debt Obligation)란 회사채나 대출채권 등으로 구성된 pool을 기초자산으로 하여 AAA등급에서 equity(non-rated)까지의 다양한 신용등급으로 발행된 여러 종의 선·후순위 채권을 말하며, 기초자산의 종류에 따라 회사채를 기초자산으로 하는 회사채 담보부증권(CBO; Collateralized Bond Obligation), 대출채권을 기초자산으로 하는 대출채권 담보부증권(CLO; Collateralized Loan Obligation)으로 분류된다. 그리고 발행목적에 따라 주로 은행 등의 금융기관이 재무상태표상에서 위험자산을 제거하기 위하여 발행하는 Balance Sheet CDO와 고수익의 원자산인 대출금, 회사채 등과 선· 후순위 채권 간의 이자차익을 얻기 위해 발행하는 Arbitrage CDO 등이 있다. 미국의 모기지 전문 대출기관들은 2000년대 초중반 부동산 활황을 틈타 대출자금을 조달하기 위하여 모기지 채권이나 주택저당증권(MBS)을 대량으로 발행하였고, 투자은행들이 이를 사들여 합성한 뒤 발행한 채권이 바로 CDO였다. 2007년 주택담보대출 연체율이 높아지면서 이른바 서브프라임 모기지론 사태가 벌어져 채권 가격이 폭락함으로써 주요 금융회사 등 투자자들이 큰 손실을 입고 글로벌 금융위기로 이어지게 되었다.', related_words = ARRAY['CMO']::text[] WHERE id = 254;  -- 부채담보부증권(CDO)
UPDATE public.words SET meaning = '분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이', detailed_meaning = '분수효과(Trickle-up Effect, Fountain Effect)란 정부가 경제정책으로 저소득층과 중산층의 소득을 먼저 늘려주면 이들의 소비 확대가 생산과 투자로 이어지면서 전체 경제활동이 되살아나고 이로 인해 고소득층의 소득도 늘어날 수 있다는 주장이다. 즉 분수에서 물이 아래에서 위로 솟아나는 것처럼 저소득층에서 시작된 소득과 소비 증대의 효과가 점차상위 계층으로 확산되면서 전체 경제도 좋아질 수 있다는 것이다. 이러한 주장은 영국의 경제학자인 케인즈(J. M. Keynes)가 경제 활성화에 긴요한 총수요 진작을 위해서는 상대적으로 한계소비성향이 높은 저소득층과 중산층에 초점을 맞추어 정부지출을 늘리고 세금을 줄여야 한다는 논리에 근거하고 있다. 이는 분배보다는 성장에, 그리고 저소득층보다는 고소득층에 중점을 두어 경제정책을 운용해야 한다는 낙수효과와는 상반되는 개념이다.', related_words = ARRAY['낙수효과']::text[] WHERE id = 258;  -- 분수효과
UPDATE public.words SET meaning = '브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다.', detailed_meaning = '브레튼우즈체제는 1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다. 이 협정을 체결하게 된 배경은 1930년대 대공황의 여파로 인한 금본위제도 붕괴, 무역규제 확대, 환율 불안정에 이어 1940년대 국제유동성 부족, 외환규제 확산 등으로 국제통화질서가 위기에 직면하게 되었기 때문이다. 브레튼우즈체제는 국제통화제도의 본질적인 기능인 유동성 공급과 국제수지 조정 메커니즘을 미달러화를 기축통화로 하는 금환본위제도와 조정가능 고정환율제도를 통해서 해결하고자 하였다. 즉 각국은 달러를 대외준비자산으로 보유하고 미국은 다른 나라가 보유한 달러에 대해 금태환을 보장하며, 각국의 고정환율에 조정이 필요한 경우 국제통화기금(IMF)과 협의하여 변경할 수 있도록 하였다. 이를 뒷받침하기 위하여 설립된 국제기구가 IMF와 국제부흥개발은행(IBRD)이다. 1960년대 들어 국제유동성 수준이 미국의 국제수지 상태에 따라 결정되고 환율 변경을 통한 불균형 개선이 쉽지 않은 등의 구조적인 문제가 대두되는 가운데 1971년 미국이 달러화의 금태환을 정지하고 뒤이어 선진국들이 변동환율제도로 이행함에 따라 브레튼우즈체제는 사실상 붕괴되었다.', related_words = ARRAY['국제통화기금(IMF)','금본위제','고정환율제도/자유변동환율제도']::text[] WHERE id = 261;  -- 브레튼우즈체제
UPDATE public.words SET meaning = '사회보장제도는 개인이 어떠한 불행을 당하더라도 국가가 최소한의 인간다운 생활을 보장할 수 있도록 하는 제도이다.', detailed_meaning = '사회보장제도는 개인이 어떠한 불행을 당하더라도 국가가 최소한의 인간다운 생활을 보장할 수 있도록 하는 제도이다. 사회 불평등 현상을 해결하기 위해 도입된 것으로 사회보험과 공공부조, 사회복지서비스가 대표적이다. 사회보험(社會保險)은 산업재해, 실업, 질병 등으로 인하여 소득이 상실되었을 때를 대비한 보험으로 산업재해보험, 국민연금, 고 용보험, 건강보험이 있다. 보험료는 일반적으로 혜택을 받는 개인과 고용주 또는 국가가 나누어 부담하며, 소득이 높을수록 부담이 높아진다. 한편 공공부조(公共扶助)는 비용 전부를 국가가 부담하며 생활능력이 없는 사람의 최저한의 생활보호를 위해 마련된 제도로 기초생활보장제도가 대표적인 예이다. 마지막으로 사회복지서비스는 도움을 필요로 하는 모든 국민이 정상적인 생활을 할 수 있도록 도와주는 상담, 재활, 직업소개 및 지도 등 여러 지원제도를 의미한다. 주로 아동, 노인, 장애인을 위한 복지제도가 여기에 포함된다.', related_words = ARRAY['사회보험','상대적 빈곤율']::text[] WHERE id = 275;  -- 사회보장제도
UPDATE public.words SET meaning = '거주자와 비거주자 간의 상품 수출입 거래를 계상한 것으로, 경상수지의 한 부분이다.', detailed_meaning = '거주자와 비거주자 간의 상품 수출입 거래를 계상한 것으로, 경상수지의 한 부분이다. 수출이 수입보다 많으면 흑자, 수출보다 수입이 많으면 적자로 표시한다. 상품수지의 수출입은 관세청에서 통관기준으로 작성하는 무역수지의 수출입과 일치하지 않는 경우가 많다. 이는 관세청에서는 상품이 우리나라의 관세선을 통과하면 수출입으로 계상하는 반면, 국제수지의 상품수지에서는 상품의 소유권이 이전되어야 수출입으로 간주하는 소유권이 전(change of ownership) 기준을 따르기 때문이다. 또한 무역수지에서 수출은 FOB가 격, 수입은 운임 및 보험이 포함되어 있는 CIF가격으로 평가하지만, 상품수지에서는 수출과 수입 모두 FOB가격으로 평가한다는 차이점도 있다.', related_words = ARRAY['경상수지']::text[] WHERE id = 282;  -- 상품수지
UPDATE public.words SET meaning = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라', detailed_meaning = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라 범용 선불형카드와 단일목적 선불형카드로 구분된 다. 범용 선불형카드는 광범위한 지역에서 상품 또는 서비스 대금의 지급에 사용될 수 있는 반면 단일목적 선불형카드는 일정지역 또는 특정목적으로만 사용될 수 있다. 선불형카드는 신용카드사가 발행하는 선불카드와 은행 등 금융기관이 발행하는 전자화폐, 전자금융업자가 발행하는 선불전자지급수단으로 구분된다. 대부분의 신용카드사들은 사용한도 가 미리 정해져 있어 그 범위내에서 일반 신용카드처럼 물건이나 서비스를 구매할 수 있고 재충전(top-up)도 가능한 기명 선불카드 또는 무기명 선불카드(기프트카드)를 발행하고 있다. 선불전자지급수단은 IC카드형과 네트워크형으로 분류할 수 있는데 IC카드형은 주로 교통부문을 중심으로 이용되고 있으며 네트워크형은 사이버쇼핑몰 등의 대금결제에 주로 사용되고 있다.', related_words = ARRAY['지급수단','직불카드','전자화폐']::text[] WHERE id = 298;  -- 선불카드/선불전자지급수단
UPDATE public.words SET meaning = '소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득 수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1 분위) 계층의', detailed_meaning = '소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득 수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1 분위) 계층의 평균소득으로 나눈 값이다. 소득5분위배율 값이 커질수록 고소득층과 저소득층 간의 소득분배가 악화하였음을 의미한다.', related_words = ARRAY['상대적 빈곤율','지니계수']::text[] WHERE id = 304;  -- 소득5분위배율
UPDATE public.words SET meaning = '상품의 가격 변화비율에 대한 수요량의 변화비율을 수요의 가격탄력성(price elasticity of demand)이라 한다.', detailed_meaning = '상품의 가격 변화비율에 대한 수요량의 변화비율을 수요의 가격탄력성(price elasticity of demand)이라 한다. 탄력성은 반응의 크기를 분석하는 데 의미가 있다. 충격을 주는 쪽과 반응하는 쪽의 변화율을 비교하여 같은 경우를 단위 탄력적이라고 하고, 반응하는 쪽의 변화율이 더 높으면 탄력적, 작으면 비탄력적이라고 한다. 수요의 가격탄력성의 경우, 한 상품의 가격의 변화비율과 수요량의 변화비율이 동일할 경우 수요의 가격탄력성은 1이 되며, 이 경우 수요가 단위 탄력적이라고 한다. 수요량의 변화비율이 가격의 변화비율보다 작아서 수요의 가격탄력성이 1보다 작으면 수요가 비탄력적이라고 한다. 반면수요량의 변화비율이 가격의 변화비율보다 높아서 수요의 가격탄력성이 1보다 크게 되면수요가 탄력적이라고 한다.', related_words = ARRAY['공급탄력성']::text[] WHERE id = 317;  -- 수요탄력성
UPDATE public.words SET meaning = '수출입물가지수는 수출 및 수입상품의 가격변동을 측정하는 지표로서 동 지수는 대외의 존도가 높은 우리나라의 경우 수출입상품의 가격변동이 국내물가, 생산활동 및 대외 경쟁등에 미치는 효과를 사전에', detailed_meaning = '수출입물가지수는 수출 및 수입상품의 가격변동을 측정하는 지표로서 동 지수는 대외의 존도가 높은 우리나라의 경우 수출입상품의 가격변동이 국내물가, 생산활동 및 대외 경쟁등에 미치는 효과를 사전에 측정하기 위해 작성되며 주로 수출입관련업체들의 수출채산성 변동이나 수입원가 부담 등을 파악하는 한편 수출입물가지수의 상호 비교를 통하여 가 격측면에서의 교역조건 등을 측정하는 데 이용된다. 2025년 8월 기준으로 조사대상품목이 수출물가지수는 212개, 수입물가지수는 237개이며, 조사되는 가격기준은 수출 FOB, 수입 CIF를 원칙으로 하고 있다.', related_words = ARRAY['수출입물량지수']::text[] WHERE id = 322;  -- 수출입물가지수
UPDATE public.words SET meaning = '순상품교역조건지수란 수출 1단위로 수입할 수 있는 상품의 양이 기준시점 대비 얼마나 증가하였는지를 나타내며, 무역지수통계에서 작성된 수출가격물가지수를 수입물가지수로 나누어 산출한다.', detailed_meaning = '순상품교역조건지수란 수출 1단위로 수입할 수 있는 상품의 양이 기준시점 대비 얼마나 증가하였는지를 나타내며, 무역지수통계에서 작성된 수출가격물가지수를 수입물가지수로 나누어 산출한다. 예를 들어, 2024년 12월 순상품교역조건지수 93.25는 수출 1단위로 수입할 수 있는 상품의 양이 2020년 1~12월의 평균 대비 6.75% 감소하였음을 의미하며, 수출 1단위로 0.9325단위 상품을 수입할 수 있다는 의미가 아니다. 순상품교역조건지수가 상승했다는 것은 수출물가가 수입물가보다 더 많이 올랐다거나 수출물가가 수입물가보다 덜 하락했다는 것을 의미한다. 따라서 순상품교역조건지수가 상승하면 1단위상품을 수출해서 받은 외화로 이전보다 더 많은 양의 상품을 수입할 수 있게 된다. 반대로 순상품교역조건지수가 하락했다는 것은 1단위 상품을 수출함으로써 수입할 수 있는 상품의 양이 그 이전에 비해 줄어들었음을 의미하며 이처럼 교역조건이 악화되면 국민경제의 실질구매력이 떨어져 실질소득이 감소하고 경상수지가 악화될 수 있다.', related_words = ARRAY['무역지수','수출입물가지수']::text[] WHERE id = 325;  -- 순상품교역조건지수
UPDATE public.words SET meaning = '스테이블코인은 가격변동성이 최소화되도록 설계된 가상자산을 의미한다.', detailed_meaning = '스테이블코인은 가격변동성이 최소화되도록 설계된 가상자산을 의미한다. 비트코인 등 대부분의 가상자산은 가격 변동성이 커서 실제로는 화폐로서의 수용성이 제한되므로 가 격 변동성을 최소화할 필요성이 대두되었다. 스테이블코인은 가격변동 최소화를 위한 연동대상 자산과 방법에 따라 법정화폐 담보형 및 암호자산 담보형, 알고리즘형 등으로 분류된다. 법정화폐 담보형은 미국 달러화, 유로화 등 기존 화폐를 담보로 제공하고 담보가 치만큼 스테이블코인을 발행하는 방식이다. 암호자산 담보형은 비트코인 등과 같은 주요 암호자산을 담보로 발행하는 방식이다. 알고리즘형은 스테이블코인의 공급량을 자동적으로 조정하는 알고리즘을 내재하여 가치를 안정시키는 방식이다. 스테이블코인은 가상자산을 이용한 지급 및 송금의 효율성 제고, 금융포용성 증가 등의 긍정적 효과가 기대되나 담보자산 가치하락, 알고리즘에 대한 신뢰 부재 등으로 가격변동성이 확대될 가능성이 완전히 사라지지 않을 수 있음에 유의하여야 한다.', related_words = ARRAY['가상자산','비트코인']::text[] WHERE id = 336;  -- 스테이블코인
UPDATE public.words SET meaning = '시장평균환율이란 외국환중개회사를 통해 거래가 이루어진 현물환매매 중 결제일 2영업일 전 현물환시장에서 형성되는 환율과 그 거래량을 가중평균하여 산출한 환율을 의미한 다.', detailed_meaning = '시장평균환율이란 외국환중개회사를 통해 거래가 이루어진 현물환매매 중 결제일 2영업일 전 현물환시장에서 형성되는 환율과 그 거래량을 가중평균하여 산출한 환율을 의미한 다. 우리나라는 환율의 시장기능을 제고하기 위해 1990년 3월 시장평균환율제도를 도입하였다. 시장평균환율은 다음 영업일의 기준환율이 되며 이 기준환율을 중심으로 상하 일정 범위 내에서만 환율이 변동되도록 하는데, 시장평균환율제도 도입 당시에는 일일 환율변동제한폭을 기준환율을 중심으로 상하 0.4%로 설정하였으며 이후 변동제한폭을 지속적으로 확대하였다. 1997년 외환위기에 직면하면서 변동제한폭을 상하 10%로 대폭 확대하였다가 같은 해 12월 이를 완전히 폐지함으로써 자유변동환율제도로 이행하였다. 한편시장평균환율은 외국환거래규정에서 정의하고 있는 매매기준율로서 외국환포지션한도의 관리, 기업의 외화자산·부채 평가 등 다양한 분야에서 사용된다. 우리나라 외환시장에서 는 이러한 시장평균환율로 상당한 규모의 현물환 거래(이를 MAR거래라 한다.)가 이루어지고 있다.', related_words = ARRAY['시장평균환율제도']::text[] WHERE id = 344;  -- 시장평균환율(MAR)
UPDATE public.words SET meaning = '금융기관 등에서 돈의 공급이 원활히 이루어지지 않아 어려움을 겪는 현상을 의미한다.', detailed_meaning = '금융기관 등에서 돈의 공급이 원활히 이루어지지 않아 어려움을 겪는 현상을 의미한다. 신용경색은 금융시장에 공급된 자금의 절대량이 적거나 자금의 통로가 막혀 있을 때 주로 발생한다. 신용경색(Credit Crunch)이 발생하면 기업들은 자금 부족으로 인해 정상적인경영 활동에 어려움을 겪게 되고 무역업체들도 수출입 활동에 큰 제약을 받게 된다. 신용경색이 나타나는 과정은 보통 다음과 같다. 먼저 일부 은행의 도산이나 부실화로 인해 금융시스템 내의 대출 가능 규모가 줄어들게 되고, 이들 은행과 거래하던 기업들의 차입이 어려워지면서 기업 도산확률이 높아지게 된다. 이렇게 되면 건전한 은행들도 높아진 기업의 신용위험과 유동성 위험 등에 대비하여 대출 규모를 축소하기 때문에 금융시스템 내유동성이 부족해져 자금공급이 더욱 위축되는 악순환이 발생하게 된다. 신용경색은 주식, 채권 등 직접금융시장이 발달하지 못한 경우 실물경제에 더 큰 충격을 준다. 부문별로는 신용도가 낮은 중소기업이나 가계와 같이 직접금융시장을 이용하기 어려운 부문에 더 큰영향을 미치게 된다. 우리나라도 1998년 외환위기 시 극심한 신용경색으로 인해 많은 기업이 도산한 경험이 있다.', related_words = ARRAY['신용위험(신용리스크)','유동성리스크']::text[] WHERE id = 348;  -- 신용경색
UPDATE public.words SET meaning = '바젤 자본규제에서는 신용위험을 채권·채무관계에서 채무자의 채무불이행, 이행거부 또는 신용도 하락 등으로 인해 발생하는 손실 가능성을 포괄하는 개념으로 정의한다.', detailed_meaning = '바젤 자본규제에서는 신용위험을 채권·채무관계에서 채무자의 채무불이행, 이행거부 또는 신용도 하락 등으로 인해 발생하는 손실 가능성을 포괄하는 개념으로 정의한다. 규제하에서 신용위험은 일정 기간(통상 1년) 이내에 발생할 수 있는 발생할 것으로 예상되는 부도율(PD; Probability of Default), 채무불이행이 발생했을 때 담보 등을 고려한 실제손실 비율(LGD; Loss Given Default), 부도 시 익스포저(EAD; Exposure At Default) 등의 지표를 통해 체계적으로 산출하되 예상을 벗어나는 충격적 손실(예상외 손실, UL; Unexpected Loss)도 신용위험에 포함한다.', related_words = ARRAY['예상손실']::text[] WHERE id = 352;  -- 신용위험(신용리스크)
UPDATE public.words SET meaning = '넓은 의미에서 신용평가란 자금을 빌리는 가계, 기업 등 차입자의 부채 상환능력이나 신용도를 일정한 등급으로 평가하는 것을 말한다.', detailed_meaning = '넓은 의미에서 신용평가란 자금을 빌리는 가계, 기업 등 차입자의 부채 상환능력이나 신용도를 일정한 등급으로 평가하는 것을 말한다. 대표적인 예로서는 먼저 기업이 증권을 발행할 때 신용평가회사가 기업의 신용을 평가해주는 것이 있고, 다음으로 은행 등 금융기관이 고객에게 대출을 할 때 개인 등의 신용등급을 평가하는 제도가 있다. 신용평가 회사(CRAs; Credit Rating Agencies)는 채권을 발행하려는 기업이나 금융기관의 재무상황, 경제적 여건 등을 감안하여 발행자의 신용도를 등급으로 제시한다. 신용평가회사는 1800년대 미국에서 채무자의 신용을 평가하기 위해 도입되었다. 1841년 태펀(Lewis Tappan)은 상인들의 신용을 평가하는 회사를 설립하였는데 현재 세계 신용평가회사 중하나인 Moody’s Investors Service로 발전하였다. 1990년대에 들어서 이러한 신용평가 는 투자자에 대한 자료제공 이외에 금융기관이 등급이 낮은 채권 보유를 일정량 이상 보유하는 것을 제한함으로써 건전성감독의 수단으로도 활용되고 있다. 한편 가계대출 등에 이용되는 개인신용평가제도(CSS; Credit Scoring System)는 개인의 인적사항, 소득, 금융기관 거래 및 대출실적 등 신용정보를 토대로 신용등급을 매겨 대출여부 결정, 대출가 능금액 및 적용금리 산정 등에 활용된다.', related_words = '{}'::text[] WHERE id = 355;  -- 신용평가제도
UPDATE public.words SET meaning = 'EMBI+(Emerging Market Bond Index+)는 신흥국(이머징 마켓) 정부가 국제금융시장에서 발행한 달러화 표시 국채의 수익률을 기반으로 하는 대표적인 벤치마크 지수로 글로 벌', detailed_meaning = 'EMBI+(Emerging Market Bond Index+)는 신흥국(이머징 마켓) 정부가 국제금융시장에서 발행한 달러화 표시 국채의 수익률을 기반으로 하는 대표적인 벤치마크 지수로 글로 벌 투자은행인 JP Morgan이 산출한다. 구체적으로는 신흥시장국 채권 등의 가산금리를 거래금액을 기준으로 가중평균하여 지수화한다. 미국, 유럽, 일본 등 신용등급이 높은 국가에서 발행한 채권에 주로 투자하는 펀드를 글로벌 채권펀드, BRICs 등 신흥시장 국가 에서 발행한 채권에 주로 투자하는 펀드를 신흥시장국 채권펀드라고 하는데, 양자간 투자위험도의 차이 때문에 통상 후자의 금리(투자수익률)는 전자의 금리보다 높다. EMBI+ 수익률에서 미국 국채수익률을 차감한 값을 EMBI+ 스프레드라고 하며, 일반적으로 신흥국의 위험이 증가하면 동 스프레드가 커진다.', related_words = ARRAY['MSCI 지수','FTSE 지수']::text[] WHERE id = 358;  -- 신흥시장국채권지수(EMBI+)
UPDATE public.words SET meaning = '아시아개발은행(ADB)은 아시아·태평양 지역의 경제성장 및 경제협력 촉진과 역내 개도 국의 경제개발 지원을 목적으로 1966년 8월 설립된 국제금융기구로서 필리핀 마닐라에 본부를 두고 있다.', detailed_meaning = '아시아개발은행(ADB)은 아시아·태평양 지역의 경제성장 및 경제협력 촉진과 역내 개도 국의 경제개발 지원을 목적으로 1966년 8월 설립된 국제금융기구로서 필리핀 마닐라에 본부를 두고 있다. 주요 기능은 공공 및 민간자본의 역내 개발투자 촉진, 역내 국가의 균형적 경제발전을 위한 회원국의 개발사업에 대한 자금지원, 개발사업계획의 작성 및 집행에 관한 기술지원 등이다. 이에 따라 회원국의 출자금과 차입금 등으로 조달된 일반재원의 투자 및 융자, 회원국의 출연금으로 조성한 아시아개발기금의 운영 등의 업무를 수행하고 있다. ADB(Asian Development Bank) 조직은 총회, 이사회 및 총재를 비롯한 실무부서로 구성되어 있다. 가입 자격은 역내 국가의 경우 UN, UN 전문기구, ESCAP의 회원국이어야 하며 역외 국가는 선진국으로 제한하고 있는데 2025년 6월말 현재 회원국은 총 69개국(역내 50개국, 역외 19개국)이다. 회원국의 투표권은 기본표와 비례표로 구분되는 데 기본표는 총 투표권의 20%를 회원국에 균등하게 배분하고 비례표는 1주당 1표씩 출자액에 비례하여 배분한다. 2024년 말 현재 회원국별 투표권 비중을 보면 미국과 일본이 각각 12.747%로 가장 높고 중국(5.43%), 인도, 호주, 인도네시아, 캐나다, 한국(4.31%)의 순이다.', related_words = '{}'::text[] WHERE id = 368;  -- 아시아개발은행(ADB)
UPDATE public.words SET meaning = '영끌 “영혼까지 끌어 모은다”의 줄임말로 주로 부동산이나 주식 등 자산을 매입하기 위해개인이 보유한 자금과 대출 등을 통해 조달가능한 모든 자금을 총동원하여 투자하는 행위를 말한다.', detailed_meaning = '영끌 “영혼까지 끌어 모은다”의 줄임말로 주로 부동산이나 주식 등 자산을 매입하기 위해개인이 보유한 자금과 대출 등을 통해 조달가능한 모든 자금을 총동원하여 투자하는 행위를 말한다. 자기자본 외에도 신용대출, 전세자금대출, 마이너스통장, 카드론 등 가능한 모든 금융수단을 활용하며 부모나 지인들로부터의 자금 차입도 포함된다. 이 용어는 2020 년대 초반 한국의 부동산 가격 급등기에 유행하면서 널리 알려졌다. 특히 청년층 사이에 서 “지금 사지 않으면 평생 집을 못 살 수 있다”는 불안심리가 퍼지면서 극단적인 금융 레버리지 활용이 증가했다. 이러한 행동은 일시적으로 자산을 마련할 수 있지만 향후 금리상승, 자산 가격 하락, 소득 감소 등의 위험에 매우 취약하다. 정부는 대출 규제 강화(예: DSR 규제)를 통해 차주의 상환능력에 기반한 대출 관행을 정착시키기 위한 노력을 기울이고 있다. 영끌은 ‘빚투(빚내서 투자)’와 함께 동시대 개인투자자의 위험성 높은 투자 행태를 대표하는 용어로 사용된다.', related_words = '{}'::text[] WHERE id = 386;  -- 영끌
UPDATE public.words SET meaning = '유동성커버리지비율(LCR; Liquidity Coverage Ratio)은 단기 유동성 규제비율로서 은행이 유동성 부족에 대비하여 보유한 고유동성자산 규모를 30일간의 유동성스트레스 시나 리오', detailed_meaning = '유동성커버리지비율(LCR; Liquidity Coverage Ratio)은 단기 유동성 규제비율로서 은행이 유동성 부족에 대비하여 보유한 고유동성자산 규모를 30일간의 유동성스트레스 시나 리오 하에서 예상되는 순현금유출액으로 나눈 비율이다. LCR의 산식은 ‘고유동성자산 / 향후 30일간 순현금유출액(현금유출액 - 현금유입액) × 100’이다. 분자의 고유동성자산은 현금은 물론 정부 및 중앙은행이 발행하는 채무증권, 은행이 중앙은행에 예치한 지급준비금 등으로 구성된다. 분모의 순현금유출액은 30일 동안의 심각한 위기상황에서 발생할 것으로 예상되는 현금유출액에서 현금유입액을 차감하여 산출한다. 일반은행이 준수해야 하는 LCR 규제비율은 2015년 80%에서 2019년 100%로 점진적으로 도입되었다. 코로나19 사태 이후 금융권의 가계대출 및 기업 자금 공급 확대를 위해 2020년 일시적으로 기존 100%에서 85%로 인하하였으나 2022년부터 단계적 상향을 통해 2025년 7월 말 현재 100%를 준수하여야 한다.', related_words = ARRAY['유동성리스크','순안정자금조달비율']::text[] WHERE id = 430;  -- 유동성커버리지비율
UPDATE public.words SET meaning = '의중임금이란 유보임금이라고도 하는데 특정 근로자로 하여금 노동을 공급하게 하기 위해 지불해야 할 최소한의 임금을 말한다.', detailed_meaning = '의중임금이란 유보임금이라고도 하는데 특정 근로자로 하여금 노동을 공급하게 하기 위해 지불해야 할 최소한의 임금을 말한다. 다시 말해 노동을 공급할 의사가 있는 근로자가 받고자 하는 최소한의 임금이라고 할 수 있다. 따라서 취업자들은 현직에서 받는 임금이 자신들이 염두에 두고 있던 임금보다 높은 사람들이다. 의중임금은 실업기간에 중요한 영향을 미친다. 구직활동기간을 종료시키는 경로는 두 가지인데 하나는 구직활동을 포기하고 비경제활동 상태로 전환하는 경우이고 다른 하나는 취업을 하는 경우이다. 후자는 자신에게 제시된 임금이 자신의 유보임금보다 높을 때 발생한다. 따라서 다른 조건이 같을 경우 유보임금이 높을 때 실업기간은 길어지게 된다.', related_words = ARRAY['통상임금']::text[] WHERE id = 441;  -- 의중임금
UPDATE public.words SET meaning = '물가수준이 지속적으로 상승하는 현상을 인플레이션이라고 한다.', detailed_meaning = '물가수준이 지속적으로 상승하는 현상을 인플레이션이라고 한다. 여기서 물가는 개별상품의 가격을 평균하여 산출한 물가지수를 의미한다. 인플레이션은 물가상승 지속기간 및상승폭, 제품의 질적 수준 향상 여부, 정부의 가격통제에 따른 암시장 가격 상승 여부와 같은 점을 고려할 때 언제 인플레이션이라고 정의할 것인가에 대해 이견이 있을 수 있다. 통상 연 4~5% 정도의 물가상승률이 관측되면 일반적으로 인플레이션이 발생했다고 판단한다.', related_words = ARRAY['디스인플레이션','디플레이션']::text[] WHERE id = 454;  -- 인플레이션
UPDATE public.words SET meaning = '증권거래법, 간접투자자산운용업법, 신탁업법 등 자본시장 관련 6개 법률을 통합한 「자본시장과 금융투자업에 관한 법률」(2009년 2월 시행)을 말한다.', detailed_meaning = '증권거래법, 간접투자자산운용업법, 신탁업법 등 자본시장 관련 6개 법률을 통합한 「자본시장과 금융투자업에 관한 법률」(2009년 2월 시행)을 말한다. 동 법률의 목적은 자본시장과 금융투자업에 관한 규제를 개편하여 금융혁신과 경쟁을 촉진하고 대형 투자은행 육성과 자본시장 활성화 등 직접금융시장을 확충함으로써 기존 은행중심의 간접금융체계와 조화를 도모하기 위한 기반을 조성하는 것이었다. 금융투자업을 투자매매업·투자중개업· 집합투자업·신탁업·투자일임업·투자자문업 등 6개로 구분하고 동 업무를 영위하려는 자로 하여금 원하는 업무를 복수 또는 단수로 선택적으로 인가를 받거나 등록을 한 후 영업을 할 수 있도록 하였다. 이와 관련하여 이해 상충 발생 가능성이 높다고 인정되는 금융투자업 간에는 매매에 관한 정보제공 금지, 임직원의 겸직제한, 사무공간 등의 공동이용 제한 등을 의무화하였다. 또한 고유자산 및 운용자산이 각각 2조원 이상, 6조원 이상인 금융투자업자는 의무적으로 사외이사를 선임하고 감사위원회를 설치하도록 하였다. 동 법은 금융투자상품을 포괄주의에 입각하여 원본손실이 발생할 가능성이 있는 모든 금융상품으로 정의하였다. 금융투자상품을 증권, 장내파생금융상품, 장외파생금융상품으로 구분하고 증권은 다시 채무증권, 지분증권, 수익증권, 증권예탁증권, 투자계약증권, 파생결합증권 등으로 구분하였다.', related_words = ARRAY['간접금융/직접금융']::text[] WHERE id = 471;  -- 자본시장법
UPDATE public.words SET meaning = '상품의 특성 때문에 시장에서 자연스럽게 생겨난 독점을 말한다.', detailed_meaning = '상품의 특성 때문에 시장에서 자연스럽게 생겨난 독점을 말한다. 자연독점(Natural Monopoly)은 생산규모가 커질수록 생산비용이 계속 낮아지는 규모의 경제(economies of scale)가 존재할 때 발생한다. 규모의 경제가 큰 산업의 경우에는 시장에 먼저 진입하여 대규모 생산능력을 갖춘 선발기업이 가격경쟁력을 바탕으로 다른 후발기업의 시장진입을 자연스럽게 봉쇄할 수 있다. 예를 들어 지역 주민에게 수돗물을 공급하는 경우 공급자는 도시 곳곳에 수도관을 설치해야 한다. 이때 복수의 공급자가 수돗물을 공급한다면공급자마다 수도관을 설치해야 하는데, 이를 위해서는 막대한 고정비용을 지출해야 한다. 따라서 수돗물을 공급하는 평균비용은 하나의 공급자가 존재할 때 가장 낮다. 전기나 전화 등을 공급하는 경우도 마찬가지이다. 자연독점은 초기 투자비용이 커서 투자비용 회수에 오랜 기간이 걸린다는 특징을 가지고 있다. 자연독점은 생산 면에서는 가장 효율적이 지만, 소비자로서는 독점의 피해가 나타날 수도 있기 때문에 많은 나라에서는 자연독점기업이 적당한 가격을 유지하도록 규제하고 있다.', related_words = ARRAY['규모의 경제']::text[] WHERE id = 476;  -- 자연독점
UPDATE public.words SET meaning = '협정을 체결한 국가 간에 상품이나 서비스 교역에 대한 관세 및 무역장벽을 철폐함으로써무역특혜를 서로 부여하는 협정을 말한다.', detailed_meaning = '협정을 체결한 국가 간에 상품이나 서비스 교역에 대한 관세 및 무역장벽을 철폐함으로써무역특혜를 서로 부여하는 협정을 말한다. 자유무역협정(FTA; Free Trade Agreement) 은 그동안 유럽연합(EU)이나 북미자유무역협정(NAFTA) 등과 같이 인접국가나 일정한 지역을 중심으로 이루어졌기 때문에 흔히 지역무역협정(RTA; Regional Trade Agreement) 이라고도 불린다. 자유무역협정은 체결국간 경제통합의 심화정도에 따라 회원국간 관세를 포함하여 각종 무역제한조치를 철폐하는 자유무역협정, 회원국간 역내무역 자유화 외에도 역외국에 대해 관세에 대한 공동보조를 취하는 관세동맹, 회원국간 노동, 자본 등 생산요소의 자유로운 이동이 가능한 공동시장, 회원국들이 독립된 경제정책을 철회하고 단일경제체제하에서 모든 경제정책을 통합 운영하는 완전경제통합 등의 4단계로 구분된다. 자유무역협정은 국가 간 합의된 내용에 대해 무역장벽을 완화하되 제삼국에 대해서 최혜국대우부여를 원칙으로 하는 세계무역기구(WTO)의 다자간무역협정과는 차이가 있다. 한편 자유무역협정은 전통적으로 상품분야의 무역자유화 또는 관세인하에 중점을 두는 경우가 많았으나 최근에는 그 적용 범위가 서비스, 투자, 지적 재산권, 정부조달, 정책 등으로까지 확대되고 있다. 2024년 말 기준 우리나라는 59개국과 21건의 자유무역협정을 체결하였다.', related_words = ARRAY['상계관세']::text[] WHERE id = 479;  -- 자유무역협정(FTA)
UPDATE public.words SET meaning = '장단기금리차란 일정 시점에서 장기금리와 단기금리의 차이를 의미한다.', detailed_meaning = '장단기금리차란 일정 시점에서 장기금리와 단기금리의 차이를 의미한다. 장단기금리차는 다양한 만기의 지표금리를 이용해서 산출할 수 있다. 예를 들어 어떤 시점에서 국고 채금리(3년 만기)가 2.0%이고 한국은행 정책금리가 1.5%라면 여기서 장단기금리차는 0.5%p(2.0%-1.5%)이다. 또는 10년만기 국고채금리와 3년만기 국고채금리의 차이도 또하나의 장단기금리차로 이해할 수 있다. 여기서의 장단기는 통상 1년을 기준으로 하기 보다는 비교하려는 만기의 상대성에 달려있다. 즉 후자의 예에서 10년을 장기로 보는 경우 3년은 단기의 의미로 비교된 것이다. 장단기금리차는 시장이 경제를 어떻게 바라보고 있는지를 판단하는데 유용한 지표로 활용된다. 장단기금리차가 줄어들고 있다면(정책금리는 한국은행이 결정하기 때문에 새로운 정책금리 결정이 나오기 전까지는 변함이 없는 반면 장기금리는 하락) 이는 경제성장률이 떨어지고 실업률이 상승하는 등 향후 경제가 더나빠질 것으로 시장이 기대한다고 볼 수 있다. 특히 이런 상황에서 경기진작을 위해 한국은행이 정책금리를 인하할 것이라는 기대가 강화되는 경우에는 이런 현상이 더욱 두드러진다. 시장이 정책금리 인하를 극단적으로 기대하는 경우에는 3년 국고채금리가 한국은 행 정책금리를 하회하는 현상도 발생한다. 이를 장단기금리 역전이라고 한다. 반대로 장단기금리차가 확대되고 있다면 향후 경제가 좋아질 것이라고 시장이 기대한다고 볼 수 있다. 특히 경제성장률이 잠재성장률에 근접하고 있어 한국은행이 정책금리를 인상할 것이 라는 기대가 형성되는 경우 그 차이는 더욱 확대된다. 또한 장단기금리차는 채권의 수급에 의해서도 영향을 받는다. 장기채권에 대한 수요가 많아지면 장기금리가 하락하여 장단기금리차가 축소되고 장기채권의 공급이 많아지면 장기금리가 상승하여 장단기금리차가 확대된다. 장단기금리차의 변화는 수익률곡선의 형태가 가팔라지거나(steepening) 평탄해지는(flattening) 것으로 표현되기도 한다. 수익률곡선이 가팔라진다는 것은 장단기금리차가 확대되는 것을 의미하고 수익률곡선이 평탄해진다는 것은 장단기금리차가 축소되는 것을 의미한다.', related_words = ARRAY['기준금리']::text[] WHERE id = 487;  -- 장단기금리차
UPDATE public.words SET meaning = '정부의 수입과 지출의 차이를 재정수지라고 한다.', detailed_meaning = '정부의 수입과 지출의 차이를 재정수지라고 한다. 수입과 지출이 같으면 균형, 수입이 더많으면 흑자, 지출이 더 많으면 적자라고 한다. 재정적자가 발생하면 국채발행이나 차입이 늘어나 정부부채가 증가하게 된다. 정부의 재정활동은 조세와 정부지출의 형태로 가계의 소비와 기업의 투자라는 거시경제의 순환에 영향을 주게 된다. 재정지출로 정부서비스가 생산되지만 일정 부문은 조세 등으로 조달된 자금이 타 부문으로 이전되는 성격도 갖고 있다. 그래서 재정적자가 과다하지 않도록 유로존(EU)은 안정성장 협약에 의거 회원국들의 재정적자를 GDP의 3% 이내, 장기적인 정부부채는 GDP의 20%를 넘지 않도록 관리하고 있다. 한편 우리나라는 당해 연도의 총수입에서 총지출을 뺀 것을 “통합재정수지” 라고 지칭하고, 통합재정수지에서 국민연금기금, 사립학교교직원연금기금, 산업재해보상보험및예방기금 등 사회보장성 기금의 수지를 제외한 재정수지를 별도로 “관리재정수지” 라고 별도로 산출 운용하고 있다. 이는 사회보장성 기금수입은 장기적인 미래지출을 위한 것으로 당해 연도의 재정활동 결과로 보기 곤란하며 기금의 성숙도에 따라 대규모 흑자나 적자가 발생하여 당해 연도의 재정활동을 판단하는데 효과적이지 않을 수 있기 때문이다.', related_words = ARRAY['국채']::text[] WHERE id = 490;  -- 재정수지
UPDATE public.words SET meaning = '전자금융공동망은 ARS공동망을 확대 개편하여 2001년 4월부터 가동된 시스템으로 인터넷뱅킹, 모바일뱅킹 등 전자금융서비스에 대한 중계업무를 처리하고 있다.', detailed_meaning = '전자금융공동망은 ARS공동망을 확대 개편하여 2001년 4월부터 가동된 시스템으로 인터넷뱅킹, 모바일뱅킹 등 전자금융서비스에 대한 중계업무를 처리하고 있다. 전자금융공동망의 대상 업무는 유·무선전화, PC 등의 매체를 통해 이루어지는데 크게 대고객업무와 중계업무로 구분된다. 대고객업무는 예금잔액 및 신용카드 관련 각종 정보조회업무, 수표의 사고유무 조회 및 환율조회 등이며, 중계업무에는 타행이체, 타행이체 거래확인 조회 및자기앞수표 조회 업무 등이 있다. 전자금융공동망을 이용할 수 있는 예금계좌에는 보통예금, 당좌예금, 저축예금, 기업자유예금, 투자자예탁금 등이 있다. 은행의 전자금융업무 운영시간은 연중무휴로 00시 05분부터 23시 55분까지로 하되, 공동운영시간대인 07시부터 23시 30분 이외 시간대의 운영여부는 참가기관이 자율적으로 정하고 있다.', related_words = ARRAY['소액지급시스템']::text[] WHERE id = 498;  -- 전자금융공동망
UPDATE public.words SET meaning = '전자화폐공동망은 금융기관이 공동으로 개발한 한국형 전자화폐(K-CASH) 이용시 발생한 금융기관간 정산금액을 결제하기 위한 시스템으로 2000년 7월 가동되었다.', detailed_meaning = '전자화폐공동망은 금융기관이 공동으로 개발한 한국형 전자화폐(K-CASH) 이용시 발생한 금융기관간 정산금액을 결제하기 위한 시스템으로 2000년 7월 가동되었다. K-CASH 이 용자가 본인의 예금을 기반으로 전자화폐에 가치를 저장하면, 발행은행은 고객의 예금계좌에서 전자화폐 구매금액을 인출하여 선불계정에 예치한다. 구매거래가 발생하여 금융결제원으로부터 지급 및 정산내역을 전송받으면, 결제할 금액을 선불계정에서 인출하여 한국은 행과의 차액결제를 통해 매입은행에 이체한다. 한편 2013년 3월 국내은행들과 금융결제원이 공동개발한 모바일지갑 서비스인 뱅크월렛(BankWallet)의 선불전자지급수단인 뱅크머니(BankMoney)도 전자화폐공동망을 이용하여 개인간 송금 서비스를 제공하고 있다. 전자화폐 거래의 결제과정에는 발행은행, 매입은행, VAN사업자 및 전자화폐공동망센터(금융결제원)가 참여하고 있으며, 은행간 거래차액의 결제는 한은금융망을 통해 이루어진다.', related_words = ARRAY['소액지급시스템','전자화폐']::text[] WHERE id = 506;  -- 전자화폐공동망
UPDATE public.words SET meaning = '정부의 재정활동과 관련하여 발생하는 모든 국고금의 수입과 지출을 관리하는 계정을 정부당좌예금계정이라 한다.', detailed_meaning = '정부의 재정활동과 관련하여 발생하는 모든 국고금의 수입과 지출을 관리하는 계정을 정부당좌예금계정이라 한다. 동 계정은 한국은행 본부에만 설치되어 있는데 한국은행 본부및 지역본부, 한국은행 국고대리점 및 체신관서 등에서 취급하는 수입금 및 지출금 등 일체의 국고금 수급 내역이 계상된다. 그러나 2003년 「국고금 관리법」의 제정으로 예외조 항이 신설됨에 따라 당행 외에 금융기관에도 예치가 가능해져 현재 금고은행에 일부 기금이 예탁되어 있다. 당행은 동 계정의 수급내역을 명확히하기 위해 일반회계, 특별회계, 기금 및 특별계정으로 구분하여 관리한다. 일반회계는 국가예산의 근간이 되는 것으로서 주로 조세와 같은 일반 세입과 국가기능 유지를 위한 일반 지출을 회계처리하기 위한 용도 이며, 특별회계는 국가가 특정사업(우편·양곡·조달관리 등)을 운영하고자 하거나, 특정한 세입으로 특정한 세출에 충당하고자 할 때 일반회계와 구분하여 회계처리하기 위한 용도이다. 기금은 특정한 분야의 사업에 대하여 지속적이고 안정적인 자금 지출이 필요하거나, 개별 법률에 의해 탄력적인 집행이 필요한 경우에 회계처리하기 위한 용도이고, 특별계정은 국고금 수급에 수반되는 자금의 흐름을 그 성격에 따라 명확하게 구분·회계처리하기 위한 용도이며 세입·세출과는 무관하게 이루어진다.', related_words = ARRAY['국고대리점']::text[] WHERE id = 510;  -- 정부당좌예금계정
UPDATE public.words SET meaning = '생산능력지수는 공급능력의 수준과 동향이 어떻게 변화하는가를 나타낸 것이며, 가동률지수는 생산실적과 생산능력의 비율인 설비이용도를 지수화한 것으로서 경기동향 분석의 기초 자료로 이용된다.', detailed_meaning = '생산능력지수는 공급능력의 수준과 동향이 어떻게 변화하는가를 나타낸 것이며, 가동률지수는 생산실적과 생산능력의 비율인 설비이용도를 지수화한 것으로서 경기동향 분석의 기초 자료로 이용된다. 두 지수는 공급능력과 설비가동의 절대수준을 나타내는 것이 아니 라 기준년도의 생산능력과 가동률을 100으로 하였을 때 비교시의 공급능력과 가동상태가 어느 수준인가를 나타낸다. 일반적으로 생산은 자가소비, 출하 및 재고변동의 합으로 표현하는데 출하가 생산보다 경기에 대해 민감(선행)한 경향이 있다. 따라서 경기가 하강하는 경우 출하는 즉시 감소하나 기업이 생산을 급격히 감소시키기 어려우므로 재고가 증가 하게 된다. 반대로 경기가 회복되는 경우 출하가 증가하면서 재고가 감소하고 뒤따라 생산이 증가하게 된다. 한편, 가동률은 경기의 움직임에 따라 변동한다. 가동률 = 생산실적/생산능력×100', related_words = ARRAY['제조업평균가동률갭']::text[] WHERE id = 517;  -- 제조업생산능력/가동률지수
